const RS=STORES.slice(1);
function rng(seed){let x=seed>>>0;return()=>{x=(Math.imul(x,1664525)+1013904223)>>>0;return x/4294967296;};}
const FN=["Ava","Liam","Noah","Emma","Olivia","Lucas","Mia","Ethan","Zoe","Owen","Leah","Ryan","Nina","Kai","Isla","Mateo","Sara","Jay","Anika","Dev","Grace","Omar","Hana","Cole","Tess","Arjun","Lena","Ravi","June","Theo"];
