function parseLast(t){if(!t||/^Never|^—/.test(t))return null;if(/^Today/.test(t))return 0;if(/^Yesterday/.test(t))return 1;const d=new Date(t+" 2026");return isNaN(d)?null:Math.max(0,Math.round((TODAY-d)/864e5));}
function targetsFor(p,users){users=users||S.users;const a=p.audience||["all"];const set=whereStores(whereOf(p));
  return users.filter(u=>u.status==="active"&&((lvl(u)<=2&&(a.includes("all")||a.includes(u.role))&&(!set||set.has(u.store)))||((u.role==="ho"||u.role==="dm"||u.role==="pcadmin")&&a.includes("ho"))));}
function mailBatch(list,ref,subject,lines,opts){const to=[...new Set((list||[]).filter(Boolean).map(x=>String(x).trim().toLowerCase()))];if(!DB.queueMail)return 0;for(let i=0;i<to.length;i+=10)DB.queueMail(Object.assign({to:to.slice(i,i+10),ref,subject,text:lines.filter(x=>x!==false).join("\n")},opts||{}));return to.length;}
/* Slack direct messages ride on the email queue: the server DMs each recipient (matched by work email)
   when Slack is on for that kind (Admin → Sign-in & security → Slack). kind: urgent | hf | sr | grow */
const slackOn=k=>!!(S.security&&S.security.slackOn&&(k==="test"||S.security["slack_"+k]===true));
const slackOpt=k=>slackOn(k)?{slack:k}:{};
function slackOnly(k,list,ref,subject,lines){if(!slackOn(k))return 0;return mailBatch(list,ref,subject,lines,{slack:k,slackOnly:true});}
/* Urgent Grind posts: DM everyone the post is for, once, when it's live (the author's browser sends it,
   including scheduled posts once their publish time has passed). */
function slackUrgentPosts(){const u=me();if(!u||!slackOn("urgent"))return;let n=0;
  (S.posts||[]).forEach(p=>{if(p.priority!=="urgent"||p.slackSent||p.author!==u.id||postState(p)!=="live")return;
    const L=targetsFor(p).map(x=>x.email).filter(Boolean);p.slackSent=new Date().toISOString();n++;
    slackOnly("urgent",L,"post:"+p.id,`🚨 Urgent: ${p.title}`,[String(p.body||"").slice(0,600),p.required?`\nPlease read and acknowledge${p.due?" by "+fmtDateY(p.due):""}.`:"",`\n${location.origin}/#grind`]);});
  if(n)save();}
function storesFor(e){return RS.filter(x=>!e.prov||e.prov==="All"||PROV[x]===e.prov);}
function taskStatus(e,store){const c=e.comp&&e.comp[store];if(c)return c;return pd(e.date)<TODAY?"overdue":"open";}
const brandForStore=x=>{const f=S.fleet&&S.fleet.find(z=>z.name===x);return (f&&brandById(f.brand))||brandById("group");};
function seedReporting(st){
  const r=rng(2026);const hasSM=new Set(st.users.filter(u=>u.role==="sm").map(u=>u.store));let n=0;
  const FAC={};RS.forEach(x=>FAC[x]=.6+r()*.38);const STORE_FACTOR=RS.map(x=>FAC[x]);
  RS.forEach((store,i)=>{const cnt=3+Math.floor(r()*4);const dom=(brandById(fleetBrandId((st.fleet.find(z=>z.name===store)||{no:100}).no,store))||{domains:["inspiredcannabis.ca"]}).domains[0];
    for(let k=0;k<cnt;k++){const f=FN[Math.floor(r()*FN.length)],l=LN[Math.floor(r()*LN.length)];
      const role=(!hasSM.has(store)&&k===0)?"sm":"store";if(role==="sm")hasSM.add(store);
      const ld=Math.floor(r()*(STORE_FACTOR[i]>.85?6:15));
      st.users.push({id:"g"+(++n),gen:true,name:f+" "+l,title:role==="sm"?"Store Manager":(k===1?"Assistant Store Manager":"Budtender"),email:(f+"."+l+n+"@"+dom).toLowerCase(),brand:"auto",role,store,status:r()<.04?"inactive":"active",auth:["Microsoft 365","Google","Email link"][Math.floor(r()*3)],last:ld===0?"Today":ld===1?"Yesterday":fmtDate(iso(new Date(2026,10,23-ld))),lastDays:ld});}
  });
  st.users.forEach(u=>{u.prov=PROV[u.store]||"BC";if(u.lastDays==null)u.lastDays=parseLast(u.last);});
  st.posts.filter(p=>p.required).forEach(p=>{const age=(TODAY-pd(p.date))/864e5;
    targetsFor(p,st.users).forEach(u=>{if(!u.gen&&(p.id==="p1"||RS.indexOf(u.store)<0))return;const pr=Math.min(.99,STORE_FACTOR[RS.indexOf(u.store)]+.06)*Math.min(1,.62+age/12);if(r()<pr&&!p.acks.includes(u.id))p.acks.push(u.id);});});
  st.events.filter(e=>e.task).forEach(e=>{e.comp=e.comp||{};const past=pd(e.date)<TODAY,days=(pd(e.date)-TODAY)/864e5;
    storesFor(e).forEach(x=>{const f=STORE_FACTOR[RS.indexOf(x)];
      if(past){if(r()<f-.02)e.comp[x]=r()<f?"on":"late";}else if(r()<f*Math.max(0,.6-days/20))e.comp[x]="on";});});
  st.links.forEach(l=>{const fav=DEFAULT_FAVS.store.includes(l.name)||DEFAULT_FAVS.sm.includes(l.name);l.clicks=Math.round((5+r()*35)*(l.min===1?2.5:l.min===2?1.6:.4)*(fav?3:1));});
  st.seeded=true;return st;
}

