const avColor=id=>AVC[parseInt(id.replace(/\D/g,""),10)%AVC.length];
/* Centre-crop an image to a square JPEG (for profile photos). */
function squareJpeg(file,size){return new Promise((res,rej)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{const c=document.createElement("canvas");c.width=c.height=size;const m=Math.min(img.naturalWidth,img.naturalHeight);
  c.getContext("2d").drawImage(img,(img.naturalWidth-m)/2,(img.naturalHeight-m)/2,m,m,0,0,size,size);URL.revokeObjectURL(url);c.toBlob(b=>b?res(b):rej(new Error("Couldn't read that image")),"image/jpeg",.85);};img.onerror=()=>{URL.revokeObjectURL(url);rej(new Error("Couldn't read that image (HEIC photos: export as JPEG first)"));};img.src=url;});}
const avatar=u=>u.photo&&/^(https:\/\/|blob:)/.test(u.photo)?`<span class="avatar ph" style="background:${avColor(u.id)}"><img src="${esc(u.photo)}" alt="" loading="lazy" referrerpolicy="no-referrer"></span>`:`<span class="avatar" style="background:${avColor(u.id)}">${esc(initials(u.name))}</span>`;
const roleChip=r=>`<span class="chip role-chip ${ROLES[r].cls}">${ROLES[r].label}</span>`;
const pd=s=>{const [y,m,d]=s.split("-").map(Number);return new Date(y,m-1,d);};
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const fmtDate=s=>pd(s).toLocaleDateString("en-CA",{month:"short",day:"numeric"});
const fmtTime=t=>{if(!t)return "All day";const [h,m]=t.split(":").map(Number);return `${(h%12)||12}:${String(m).padStart(2,"0")} ${h<12?"AM":"PM"}`;};
const ago=s=>{const d=Math.round((TODAY-pd(s))/864e5);return d<=0?"Today":d===1?"Yesterday":d<7?`${d} days ago`:fmtDate(s);};
const kindIco=k=>({pdf:["pdf","PDF"],form:["form","FRM"],xls:["xls","XLS"],app:["app","APP"]}[k]||["","LNK"]);
const catCls=c=>"c-"+c.toLowerCase();
function toast(msg){document.querySelectorAll(".toast").forEach(x=>x.remove());const t=document.createElement("div");t.className="toast";t.setAttribute("role","status");t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2600);}
function visibleLinks(u){return S.links.filter(l=>lvl(u)>=l.min && (lvl(u)>=3 || l.prov==="All" || l.prov===u.prov));}
function favsOf(u){if(!S.favs[u.id]) S.favs[u.id]=(DEFAULT_FAVS[u.role]||DEFAULT_FAVS.ho).slice();return S.favs[u.id];}
const PR={urgent:2,important:1,normal:0};
function visiblePosts(u,state){state=state||"live";return S.posts.filter(p=>postState(p)===state&&(lvl(u)>=3||seesAudience(u,Object.assign({},p,{where:whereOf(p)})))).sort((a,b)=>(b.pinned-a.pinned)||((PR[b.priority]||0)-(PR[a.priority]||0))||(pd(b.date)-pd(a.date)));}
function visibleEvents(u){return S.events.filter(e=>!e.ticketId&&seesAudience(u,e)).concat(visitEvents(u));}
function audLabel(a,p){const t=(a||["all"]).map(x=>AUD[x]).join(", ");return p&&p!=="All"?`${t} · ${p}`:t;}

