/* ---------------- Sign-in ---------------- */
function renderLogin(){
  $("#login").classList.remove("hidden");$("#app").classList.add("hidden");
  setLoginBrand(brandById("group")||S.brands[0]);
  $("#login-brands").innerHTML=S.brands.filter(b=>b.kind==="store").map(b=>`<span>${esc(b.name)}</span>`).join("");
  const sec=S.security||{};
  $("#ms-btn").classList.toggle("hidden",sec.ms===false);$("#g-btn").classList.toggle("hidden",sec.google===false);
  $("#email-block").classList.toggle("hidden",sec.email===false);
  $("#signin-block").classList.remove("hidden");$("#access-block").classList.add("hidden");
}
function renderAccess(st){
  $("#login").classList.remove("hidden");$("#app").classList.add("hidden");
  const b=brandForEmail(st.email||"")||brandById("group")||S.brands[0];if(b)setLoginBrand(b);
  $("#signin-block").classList.add("hidden");const A=$("#access-block");A.classList.remove("hidden");
  const out=`<button class="btn" data-signout>Sign out</button>`;
  if(st.kind==="loading"){A.innerHTML=`<h2>Signing you in…</h2><p class="muted">Loading the portal.</p>`;return;}
  if(st.kind==="request"){
    A.innerHTML=`<div><h2>Request access</h2><p class="muted" style="margin:4px 0 0">Signed in as <b>${esc(st.email)}</b>. Tell us where you work and Support Centre will approve your account.</p></div>
    <form id="req-form" style="display:grid;gap:12px">
      <div class="field"><label for="rq-name">Full name</label><input id="rq-name" class="input" required value="${esc(st.name||"")}"></div>
      <div class="field"><label for="rq-title">Job title</label><input id="rq-title" class="input" placeholder="e.g. Budtender, Store Manager" required></div>
      <div class="field"><label for="rq-store">Store or location</label><input id="rq-store" class="input" placeholder="e.g. Muse - Highgate, or Head Office" required></div>
      <div class="row"><button class="btn primary" type="submit">Request access</button>${out}</div></form>`;
    $("#req-form").onsubmit=e=>{e.preventDefault();const n=$("#rq-name").value.trim(),t=$("#rq-title").value.trim(),s=$("#rq-store").value.trim();
      if(!n||!t||!s){toast("Fill in all three fields.");return;}e.target.querySelector("button[type=submit]").disabled=true;DB.requestAccess({name:n,title:t,reqStore:s});};
  }
  else if(st.kind==="pending") A.innerHTML=`<h2>Waiting for approval</h2><p>Thanks${st.name?", "+esc(st.name.split(" ")[0]):""}. Your request for <b>${esc(st.email)}</b> is with Support Centre. Once an Admin approves it, sign in again and you're in.</p>${out}`;
  else if(st.kind==="inactive") A.innerHTML=`<h2>Account deactivated</h2><p>The portal account for <b>${esc(st.email)}</b> is turned off. If you think that's a mistake, contact Head Office.</p>${out}`;
  else if(st.kind==="domain") A.innerHTML=`<h2>Email not recognised</h2><p><b>${esc(st.email)}</b> isn't on one of ICG's approved email domains, so it can't request access. Sign in with your work account, or ask Support Centre to add your domain.</p>${out}`;
  else A.innerHTML=`<h2>Something went wrong</h2><p>${esc(st.msg||"")}</p>${out}`;
  A.querySelectorAll("[data-signout]").forEach(x=>x.onclick=()=>DB.signOut());
}
$("#ms-btn").onclick=()=>DB.signInMicrosoft();
$("#g-btn").onclick=()=>DB.signInGoogle();
function setLoginBrand(b){applyTheme(b);$("#login-logo").innerHTML=logoHTML(b);}
$("#email-in").addEventListener("input",e=>{
  const v=e.target.value.trim();const b=brandForEmail(v);const d=$("#detect");
  if(b){setLoginBrand(b);d.innerHTML=`${logoHTML(b)}<span>Signing in to the <b>${esc(b.name)}</b> portal</span>`;d.classList.remove("hidden");}
  else{setLoginBrand(brandById("group"));d.classList.add("hidden");}
});
$("#email-form").onsubmit=e=>{
  e.preventDefault();const v=$("#email-in").value.trim().toLowerCase();const msg=$("#email-msg");
  if(!S.security.email){toast("Email sign-in links are turned off by a Super Admin.");return;}
  if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)){msg.textContent="Enter a valid work email address.";msg.classList.remove("hidden");return;}
  DB.sendEmailLink(v).then(()=>{msg.innerHTML=`Check <b>${esc(v)}</b> for a sign-in link. Open it on this device. It works once.`;msg.classList.remove("hidden");})
    .catch(err=>{msg.textContent="Couldn't send the link ("+(err.code||err.message)+").";msg.classList.remove("hidden");});
};

/* ---------------- App shell ---------------- */
/* ---- "waiting on you" / "new since last visit" ---- */
function seenAt(k){return (S.seen||{})[k]||"";}
function markSeen(k){if(me())favsOf(me());S.seen=Object.assign({},S.seen||{},{[k]:new Date().toISOString()});save();}
const evCreated=e=>e.createdAt||(/^e(\d{13})$/.test(e.id||"")?new Date(+e.id.slice(1)).toISOString():"");
function calNew(u){const since=seenAt("cal");if(!since)return [];return visibleEvents(u).filter(e=>!e.ticketId&&!String(e.id).startsWith("ev-")&&e.author!==u.id&&e.date>=iso(TODAY)&&evCreated(e)>since);}
function grindWaitWhy(u,p){if(p.required&&!(p.acks||[]).includes(u.id)&&(lvl(u)<=2||targetsFor(p,[u]).length))return "read";const k=isTask(p)&&taskKeyFor(u,p);if(k&&!taskState(p,k).complete)return "task";return "";}
function grindWaiting(u){return visiblePosts(u).filter(p=>grindWaitWhy(u,p));}
function grindWaitTitle(u){const L=grindWaiting(u);const n=k=>L.filter(p=>grindWaitWhy(u,p)===k).length;
  return ["Waiting on you:",n("read")?n("read")+" required post"+(n("read")>1?"s":"")+" to read and acknowledge":"",n("task")?n("task")+" task"+(n("task")>1?"s":"")+" to complete":""].filter(Boolean).join("\n");}
function navItems(u){
  const cn=S.view==="calendar"?0:calNew(u).length;
  const items=[["home","Dashboard",I.home],["grind","The Grind",I.grind,grindWaiting(u).length,grindWaitTitle(u)],["calendar","Calendar",I.cal,cn,cn+" new calendar entr"+(cn===1?"y":"ies")+" since your last visit"],["resources","Resources",I.res],["pc","P&C",I.pc,pcApprovals(u).length+(isPcTeam(u)?(S.pcsubs||[]).filter(x=>["submitted","approved"].includes(x.status)).length:0),"P&C: "+pcApprovals(u).length+" waiting for your approval"+(isPcTeam(u)?", "+(S.pcsubs||[]).filter(x=>["submitted","approved"].includes(x.status)).length+" ready for P&C":"")]];
  items.push(["service","Service Requests",I.svc,srActionCount(u),srWaitTitle(u)]);
  if(canTravel(u)||(S.trips||[]).some(t=>t.approverId===u.id)) items.push(["travel","Travel",I.travel,trActionCount(u)]);
  if(canGrow(u)){const gm=gMyTasks(u);const gc=gm.filter(t=>gOver(t)||gSoon(t,7)).length;const ga=gApprWaiting(u).length;items.push(["grow","Grow",I.grow,gc+ga,[ga?ga+" approval"+(ga>1?"s":"")+" waiting for you":"",gc?gc+" of your Grow tasks are overdue or due within 7 days":""].filter(Boolean).join("\n")]);}
  if(has(u,"reports")||hfAdmin(u)) items.push(["reports","Reports",I.rep,hfAdmin(u)?hfPending().length:0,hfPending().length+" High Five"+(hfPending().length===1?"":"s")+" waiting for approval to post in The Grind"]);
  if(has(u,"fleet")) items.push(["fleet","Fleet",I.fleet]);
  if(has(u,"admin")||has(u,"users")||has(u,"links")||has(u,"audit")) items.push(["admin","Admin",I.admin]);
  if(fbCan(u)){const n=fbAdmin(u)?fbNew().length:0;items.push(["feedback","Feedback",I.fb,n,n+" new feedback item"+(n===1?"":"s")+" to review"]);}
  return items;
}
/* App icon for "Add to Home Screen" / desktop install: the signed-in user's brand. Built-in brands have
   ready-made icons and manifests in /public; a brand with an uploaded app icon uses that (iOS + browser
   tab), and the generic group manifest for Android/desktop. */
const ICON_BRANDS=["group","inspired","imagine","dutch","csc","muse","13th","burb","thc"];
let appIconFor="";
function applyAppIcon(b){if(!b)return;const key=b.id+"|"+(b.iconData?b.iconData.length:0);if(key===appIconFor)return;appIconFor=key;
  const set=(id,attr,v)=>{const el=document.getElementById(id);if(el&&v&&el.getAttribute(attr)!==v)el.setAttribute(attr,v);};
  const stat=ICON_BRANDS.includes(b.id)?b.id:"";
  set("lnk-ati","href",b.iconData||(stat?`/icons/${stat}-180.png`:"/icons/group-180.png"));
  set("lnk-fav","href",b.iconData||(stat?`/icons/${stat}-192.png`:"/icons/group-192.png"));
  set("lnk-man","href",`/manifest-${stat||"group"}.json`);
  set("meta-theme","content",b.rail||"#052553");set("meta-apptitle","content",b.name||"Retail Ops");}
// Inactivity sign-out (Settings → Security → Session timeout). Activity in any tab counts.
const IDLE_MS={"1 hour":36e5,"4 hours":144e5,"12 hours":432e5,"7 days":6048e5};
let idleWired=false;
function wireIdle(){if(idleWired)return;idleWired=true;
  const mark=()=>{try{localStorage.setItem("icg-last-active",String(Date.now()));}catch(e){}};
  let last=0;["pointerdown","keydown","scroll","touchstart"].forEach(ev=>addEventListener(ev,()=>{const n=Date.now();if(n-last>30000){last=n;mark();}},{passive:true,capture:true}));
  const check=()=>{if(!me())return;const lim=IDLE_MS[(S.security||{}).timeout]||IDLE_MS["12 hours"];let t=0;try{t=+localStorage.getItem("icg-last-active")||0;}catch(e){}
    if(!t){mark();return;}if(Date.now()-t>lim){try{localStorage.removeItem("icg-last-active");}catch(e){}logA("Signed out after inactivity");save();setTimeout(()=>DB.signOut(),300);}};
  check();setInterval(check,60000);document.addEventListener("visibilitychange",()=>{if(!document.hidden)check();});}
function renderApp(){if(me())wireIdle();
  const u=me(); if(!u){renderLogin();return;}
  $("#login").classList.add("hidden");$("#app").classList.remove("hidden");
  const ub=effBrand(u);const tb=(S.previewBrand&&brandById(S.previewBrand))||ub;
  applyTheme(tb);applyAppIcon(ub);
  $("#brandplate").innerHTML=`${logoHTML(tb)}<div class="portal-label">${tb.kind==="ho"?"Head Office · ":""}Retail Ops Portal</div>`;
  $("#preview-bar").innerHTML=S.previewBrand&&tb.id!==ub.id?`<div class="banner" style="margin:16px 24px 0"><span>Previewing the <b>${esc(tb.name)}</b> look. Content stays the same.</span><span style="flex:1"></span><button class="btn sm" data-endpreview>Exit preview</button></div>`:"";
  const bs=$("#brand-switch");bs.classList.toggle("hidden",!can.admin(u));
  const tpb=document.querySelector('[data-act="travelprof"]');if(tpb)tpb.classList.toggle("hidden",!canTravel(u));
  const fbb=document.querySelector('[data-act="feedback"]');if(fbb)fbb.classList.toggle("hidden",!fbCan(u));
  const inb=document.querySelector('[data-act="install"]');if(inb)inb.classList.toggle("hidden",isInstalled());
  $("#brand-prev").innerHTML=`<option value="">My brand (${esc(ub.name)})</option>`+S.brands.filter(b=>b.id!==ub.id).map(b=>`<option value="${b.id}" ${S.previewBrand===b.id?"selected":""}>${esc(b.name)}</option>`).join("");
  const items=navItems(u);
  updateAppBadge(items.reduce((s,i)=>s+(+i[3]||0),0));
  if(!items.find(i=>i[0]===S.view)) S.view="home";
  $("#nav").innerHTML=items.map(([k,l,ic,c,tip])=>`<button data-v="${k}" ${S.view===k?'aria-current="page"':""}>${ic}<span>${l}</span>${c?`<span class="count" title="${esc(tip||"")}" aria-label="${esc((tip||"").replace(/\n/g,", "))}">${c}</span>`:""}</button>${k==="pc"&&S.view==="pc"?pcSubnav(u):""}`).join("");
  $("#mnav").innerHTML=items.map(([k,l])=>`<button data-v="${k}" ${S.view===k?'aria-current="page"':""}>${l}</button>`).join("");
  $("#me-btn").innerHTML=`${avatar(u)}<span class="me-text"><b>${esc(u.name)}</b><small>${esc(u.title||ROLES[u.role].label)} · ${esc(u.store.split(" – ").pop())}</small></span>`;
  const V={home:viewHome,grind:viewGrind,calendar:viewCalendar,resources:viewResources,pc:viewPC,grow:viewGrow,reports:viewReports,service:viewService,fleet:viewFleet,admin:viewAdmin,travel:viewTravel,feedback:viewFeedback}[S.view];
  $("#view").innerHTML=V(u);
  if(location.hash.slice(1)!==S.view) history.replaceState(null,"","#"+S.view);
  bindView(u);
  enhanceTables($("#view"));
}
/* ---- Install the portal as an app (desktop or phone home screen) ----
   Chrome / Edge / Android offer a real "Install" prompt (captured below); Safari on iPhone, iPad and
   Mac uses Share → Add to Home Screen / Add to Dock, so we show those steps instead. */
let installEvt=null;
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();installEvt=e;document.querySelectorAll("[data-install-now]").forEach(b=>b.hidden=false);});
window.addEventListener("appinstalled",()=>{installEvt=null;toast("Installed. Open the portal from your home screen, dock or Start menu.");});
const isInstalled=()=>matchMedia("(display-mode: standalone)").matches||matchMedia("(display-mode: window-controls-overlay)").matches||navigator.standalone===true;
function installPlatform(){const ua=navigator.userAgent;const ios=/iPhone|iPad|iPod/.test(ua)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1);
  if(ios)return "ios";if(/Android/.test(ua))return "android";if(/Firefox\//.test(ua))return "firefox";if(/Edg\//.test(ua))return "edge";if(/Chrome\//.test(ua))return "chrome";if(/Safari\//.test(ua)&&/Mac/.test(ua))return "macsafari";return "other";}
/* App icon badge: the total of the sidebar counts (things waiting on you). Works in the installed app on
   Windows/Mac (Chrome, Edge, Safari "Add to Dock") and iPhone/iPad (iOS 16.4+, after allowing
   notifications). It updates whenever the portal is open or running in the background. */
let badgeLast=-1;
function updateAppBadge(n){if(n===badgeLast)return;badgeLast=n;try{if("setAppBadge" in navigator){(n>0?navigator.setAppBadge(n):navigator.clearAppBadge()).catch(()=>{});}}catch(e){}}
const badgeNeedsPermission=()=>"setAppBadge" in navigator&&"Notification" in window&&Notification.permission==="default"&&installPlatform()==="ios";
function installHTML(){if(isInstalled())return `<div class="notice" style="margin:0;display:grid;gap:8px"><span>✓ You're using the installed portal app on this device. Its icon shows a count of things waiting for you.</span>${badgeNeedsPermission()?`<span>On iPhone and iPad, allow notifications so the count can show on the icon: <button class="btn sm primary" data-badgeperm>Show counts on the app icon</button></span>`:""}${"setAppBadge" in navigator?"":`<span class="muted" style="font-size:13px">This browser doesn't support icon counts.</span>`}</div>`;
  const pf=installPlatform();const b=curBrand();
  const steps={ios:["Open the portal in <b>Safari</b> (or Chrome on iOS 16.4+).","Tap the <b>Share</b> button <span aria-hidden=\"true\">⬆︎</span> (bottom of the screen on iPhone, top on iPad).","Scroll down and tap <b>Add to Home Screen</b>, then <b>Add</b>."],
    android:["Tap <b>Install now</b> below, or open Chrome's <b>⋮</b> menu.","Choose <b>Install app</b> (or <b>Add to Home screen</b>), then <b>Install</b>."],
    chrome:["Click <b>Install now</b> below, or the install icon at the right end of the address bar.","Or open Chrome's <b>⋮</b> menu → <b>Cast, save and share</b> → <b>Install page as app</b>."],
    edge:["Click <b>Install now</b> below, or the <b>App available</b> icon in the address bar.","Or open Edge's <b>…</b> menu → <b>Apps</b> → <b>Install this site as an app</b>."],
    macsafari:["In Safari's menu bar choose <b>File</b> → <b>Add to Dock</b> (macOS Sonoma or later).","Click <b>Add</b>. The portal opens from your Dock like any other app."],
    firefox:["Firefox can't install web apps. Open the portal in <b>Chrome</b> or <b>Edge</b> and install it from there,","or pin this tab (right-click the tab → <b>Pin Tab</b>)."],
    other:["Open your browser's menu and look for <b>Install</b>, <b>Add to Home Screen</b> or <b>Add to Dock</b>."]}[pf];
  return `<div class="install-box"><div class="row" style="align-items:center;gap:12px;flex-wrap:nowrap"><img src="${esc(b.iconData||(ICON_BRANDS.includes(b.id)?"/icons/"+b.id+"-180.png":"/icons/group-180.png"))}" alt="" width="48" height="48" style="border-radius:11px;flex:none"><div><b>${esc(b.name)} portal app</b><small class="muted" style="display:block">Opens in its own window with your brand icon, like any other app. It's the same portal, always up to date.</small></div></div>
    <ol style="margin:6px 0 0;padding-left:20px;display:grid;gap:4px">${steps.map(s=>`<li>${s}</li>`).join("")}</ol>
    <div class="row"><button class="btn primary sm" data-install-now ${installEvt?"":"hidden"}>Install now</button></div></div>`;}
