/* Safari draws today's date in grey inside empty date boxes, which reads as a real date. Mark empty
   ones so CSS can hide that placeholder (everywhere: pages and pop-ups). */
const markEmptyDates=root=>{(root||document).querySelectorAll('input[type="date"]').forEach(i=>i.toggleAttribute("data-empty",!i.value));};
document.addEventListener("input",e=>{if(e.target.matches&&e.target.matches('input[type="date"]'))e.target.toggleAttribute("data-empty",!e.target.value);},true);
document.addEventListener("change",e=>{if(e.target.matches&&e.target.matches('input[type="date"]'))e.target.toggleAttribute("data-empty",!e.target.value);},true);
new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes)if(n.nodeType===1){if(n.matches('input[type="date"]'))n.toggleAttribute("data-empty",!n.value);else if(n.querySelector)markEmptyDates(n);}}).observe(document.documentElement,{childList:true,subtree:true});
/* ---- Sortable tables: click any column heading to sort (again to reverse, a third time to reset).
   Works on every table on the page; the choice is remembered while you move around the portal. ---- */
const MONTHS={jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,sept:8,oct:9,nov:10,dec:11};
function sortVal(td){if(!td)return {t:3,v:""};const raw=(td.dataset.sort!=null?td.dataset.sort:td.textContent).replace(/\s+/g," ").trim();
  if(!raw||raw==="—"||raw==="-")return {t:3,v:""};const s=raw.toLowerCase();
  const PRI={critical:0,urgent:0,high:1,important:1,medium:2,normal:2,low:3};const pw=s.replace(/^[!○✓\s]+/,"").split(/[\s(·]/)[0];if(PRI[pw]!=null&&s.length<24)return {t:0,v:PRI[pw]};
  let m=/^(\d{4})-(\d{2})-(\d{2})/.exec(raw);if(m)return {t:1,v:Date.UTC(+m[1],+m[2]-1,+m[3])+(/t(\d{2}):(\d{2})/.exec(s)?(+RegExp.$1*60+ +RegExp.$2)*6e4:0)};
  if(/^(today|yesterday)\b/.test(s)){const d=new Date(TODAY);if(s.startsWith("yesterday"))d.setDate(d.getDate()-1);const tm=/(\d{1,2}):(\d{2})\s*([ap])/.exec(s);if(tm)d.setHours((+tm[1]%12)+(tm[3]==="p"?12:0),+tm[2]);return {t:1,v:d.getTime()};}
  m=/^(?:[a-z]{3},?\s+)?([a-z]{3,4})[a-z]*\.?\s+(\d{1,2})(?:,?\s+(\d{4}))?(?:,?\s+(\d{1,2}):(\d{2})\s*([ap])?)?/.exec(s);
  if(m&&MONTHS[m[1]]!=null){const d=new Date(m[3]?+m[3]:TODAY.getFullYear(),MONTHS[m[1]],+m[2]);if(m[4])d.setHours((+m[4]%12)+(m[6]==="p"?12:0),+m[5]);return {t:1,v:d.getTime()};}
  const n=/^[#$]?-?[\d,]+(\.\d+)?\s*(%|d|days?)?$/i.test(raw.replace(/^[+−]/,""))?parseFloat(raw.replace(/[^\d.-]/g,"")):NaN;if(!isNaN(n))return {t:0,v:n};
  m=/^(\d+)\s*(of|\/)\s*(\d+)/.exec(s);if(m)return {t:0,v:+m[3]?+m[1]/+m[3]:0};
  // SLA-style durations: "Overdue 3d", "Due in 24h", "5h left"
  m=/(\d+)\s*(m|min|h|hr|d|w)\b/.exec(s);if(m&&/overdue|late|left|due|in /.test(s)){const mins=+m[1]*({m:1,min:1,h:60,hr:60,d:1440,w:10080}[m[2]]);return {t:0,v:/overdue|late/.test(s)?-mins:mins};}
  return {t:2,v:s};}
function enhanceTables(root){if(!root)return;S.tsort=S.tsort||{};
  root.querySelectorAll("table").forEach((tb,ti)=>{const head=tb.tHead&&tb.tHead.rows[0];const body=tb.tBodies[0];if(!head||!body)return;
    const rows=[...body.rows];if(rows.length<2)return;const n=head.cells.length;
    if(rows.some(r=>r.cells.length!==n||[...r.cells].some(c=>c.colSpan>1)))return; // expandable / grouped tables keep their order
    const key=S.view+"|"+ti+"|"+[...head.cells].map(c=>c.textContent.trim()).join("¦");const orig=rows.slice();
    const apply=()=>{const st=S.tsort[key];[...head.cells].forEach((th,i)=>{th.setAttribute("aria-sort",st&&st.col===i?(st.dir>0?"ascending":"descending"):"none");});
      let L=orig.slice();if(st){const vals=new Map(L.map(r=>[r,sortVal(r.cells[st.col])]));L.sort((a,b)=>{const x=vals.get(a),y=vals.get(b);if(x.t===3||y.t===3)return (x.t===3)-(y.t===3);if(x.t!==y.t)return x.t-y.t;return (x.v<y.v?-1:x.v>y.v?1:0)*st.dir;});}
      L.forEach(r=>body.appendChild(r));};
    [...head.cells].forEach((th,i)=>{if(!th.textContent.trim())return;th.classList.add("sortable");th.tabIndex=0;th.title="Sort by "+th.textContent.trim();
      const go=()=>{const st=S.tsort[key];S.tsort[key]=!st||st.col!==i?{col:i,dir:1}:st.dir===1?{col:i,dir:-1}:null;if(!S.tsort[key])delete S.tsort[key];apply();};
      th.onclick=go;th.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();go();}};});
    if(S.tsort[key])apply();});}
let tkWant=null;
function deepLink(h){if(h==="academy"){S.view="pc";S.pcTab="academy";S.pcSub=null;return true;}const gm=/^grow\/([^/]+)(?:\/(\w+))?$/.exec(h||"");if(gm){S.view="grow";S.gp=decodeURIComponent(gm[1]);S.gpTab=gm[2]||"overview";return true;}const fm=/^feedback\/(.+)$/.exec(h||"");if(fm){S.view="feedback";S.fbSel=decodeURIComponent(fm[1]);return true;}const m=/^service\/(.+)$/.exec(h||"");if(!m)return false;tkWant=decodeURIComponent(m[1]);S.view="service";return true;}
