/* Grind posts with a deadline show on the person's own calendar: required posts once they've
   acknowledged them, and task posts assigned to them. (Not shared with anyone else.) */
function postDeadlines(u){return (S.posts||[]).filter(p=>p.due&&["live","ended"].includes(postState(p))&&((p.required&&(p.acks||[]).includes(u.id))||(isTask(p)&&taskKeyFor(u,p))))
  .map(p=>({id:"pd-"+p.id,fromPost:p.id,mine:true,src:"The Grind",link:"grind",title:p.title,date:p.due,time:"",type:"deadline",desc:(p.body||"").slice(0,400),audience:p.audience||["all"],createdAt:p.date||""}));}
/* Grow deadlines on your own calendar: open Grow tasks you own (active projects) and approvals waiting
   on you that have a "needed by" date. */
function growDeadlines(u){if(!canGrow(u))return [];const out=[];
  gMyTasks(u).forEach(t=>{const p=gProj(t.pid);if(!t.due||!p||!gActive(p))return;out.push({id:"gt-"+t.id,fromGrow:p.id,mine:true,src:"Grow",link:"grow/"+p.id+"/tasks",title:`${t.title} · ${p.name}`,date:t.due,time:"",type:"deadline",desc:[t.desc,(G_TYPE[p.type]||G_TYPE.NSO)[0]+": "+p.name,t.notes].filter(Boolean).join("\n"),createdAt:""});});
  gApprWaiting(u).forEach(([p,a])=>{if(!a.due)return;out.push({id:"ga-"+a.id,fromGrow:p.id,mine:true,src:"Grow",link:"grow/"+p.id+"/appr",title:`Approve: ${a.title}`,date:a.due,time:"",type:"deadline",desc:`${G_APPR[a.kind]||""} for ${p.name}${a.amount?" · "+gMoney(a.amount):""}`,createdAt:""});});
  return out;}
const myDeadlines=u=>postDeadlines(u).concat(growDeadlines(u));
const calItems=u=>visibleEvents(u).concat(myDeadlines(u));
const calLink=e=>location.origin+"/#"+(e.link||"calendar");
/* ---- Add to Google / Outlook (M365) / Apple calendars ---- */
const icsEsc=s=>String(s||"").replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\r?\n/g,"\\n");
const icsD=s=>String(s).replace(/-/g,"");
function evTimes(e){if(!e.time)return {allDay:true,s:e.date,e:iso(new Date(pd(e.date).getTime()+864e5))};const [h,m]=e.time.split(":").map(Number);const st=new Date(pd(e.date));st.setHours(h,m||0);const en=new Date(st.getTime()+36e5);
  const f=d=>`${iso(d)}T${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}:00`;return {allDay:false,s:f(st),e:f(en)};}
function icsFor(list,name){const L=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Inspired Cannabis Group//Retail Ops Portal//EN","CALSCALE:GREGORIAN","METHOD:PUBLISH","X-WR-CALNAME:"+icsEsc(name||"ICG Portal")];
  const stamp=new Date().toISOString().replace(/[-:]/g,"").replace(/\.\d+Z$/,"Z");
  list.forEach(e=>{const t=evTimes(e);L.push("BEGIN:VEVENT","UID:"+e.id+"@icg-portal","DTSTAMP:"+stamp,
    t.allDay?"DTSTART;VALUE=DATE:"+icsD(t.s):"DTSTART:"+icsD(t.s).replace(/:/g,""),t.allDay?"DTEND;VALUE=DATE:"+icsD(t.e):"DTEND:"+icsD(t.e).replace(/:/g,""),
    "SUMMARY:"+icsEsc((e.type==="deadline"?"Deadline: ":"")+e.title),"DESCRIPTION:"+icsEsc((e.desc||"")+(e.src?"\n\nFrom "+e.src+": ":"\n\n")+calLink(e)),"END:VEVENT");});
  L.push("END:VCALENDAR");return L.join("\r\n");}
function icsDownload(list,file,name){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([icsFor(list,name)],{type:"text/calendar"}));a.download=file;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},500);}
function calLinks(e){const t=evTimes(e);const title=(e.type==="deadline"?"Deadline: ":"")+e.title;const det=(e.desc||"")+"\n\n"+calLink(e);
  const g=`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(title)}&dates=${t.allDay?icsD(t.s)+"/"+icsD(t.e):icsD(t.s).replace(/:/g,"")+"/"+icsD(t.e).replace(/:/g,"")}&details=${encodeURIComponent(det)}`;
  const o=`https://outlook.office.com/calendar/0/deeplink/compose?path=%2Fcalendar%2Faction%2Fcompose&rru=addevent&subject=${encodeURIComponent(title)}&startdt=${encodeURIComponent(t.allDay?t.s:t.s)}&enddt=${encodeURIComponent(t.allDay?t.e:t.e)}${t.allDay?"&allday=true":""}&body=${encodeURIComponent(det)}`;
  return {g,o};}
const calAddHTML=e=>{const L=calLinks(e);return `<div class="cal-add"><span class="muted" style="font-size:13px">Add to my calendar:</span><a class="btn sm" href="${esc(L.g)}" target="_blank" rel="noopener">Google</a><a class="btn sm" href="${esc(L.o)}" target="_blank" rel="noopener">Outlook / M365</a><button type="button" class="btn sm" data-calics="${esc(e.id)}">Apple / other (.ics)</button></div>`;};
function findCalItem(id){const u=me();return calItems(u).find(e=>String(e.id)===String(id));}
function openDeadlineModal(e){const p=(S.posts||[]).find(x=>x.id===e.fromPost);
  if(e.fromGrow){modal(esc(e.title),`<div class="row"><span class="chip dot t-deadline">Deadline</span><span class="chip">From Grow</span><span class="chip">Only on your calendar</span></div>
   <div><b>${pd(e.date).toLocaleDateString("en-CA",{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</b></div>${e.desc?`<p style="margin:0;white-space:pre-line">${esc(e.desc)}</p>`:""}
   <p class="muted" style="margin:0;font-size:13px">${String(e.id).startsWith("ga-")?"This approval is waiting for you.":"You own this Grow task. It leaves your calendar when it's marked done or not needed."}</p>${calAddHTML(e)}`,
   `<button class="btn" data-close>Close</button><button class="btn primary" id="dl-open">Open in Grow</button>`,()=>{$("#dl-open").onclick=()=>{closeModal();location.hash=e.link;};});return;}
  modal(esc(e.title),`<div class="row"><span class="chip dot t-deadline">Deadline</span><span class="chip">From The Grind</span><span class="chip">Only on your calendar</span></div>
   <div><b>${pd(e.date).toLocaleDateString("en-CA",{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</b></div>${e.desc?`<p style="margin:0;white-space:pre-line">${esc(e.desc)}${p&&(p.body||"").length>400?"…":""}</p>`:""}
   <p class="muted" style="margin:0;font-size:13px">${p&&isTask(p)?"This task is assigned to you.":"Added to your calendar when you acknowledged the post."}</p>${calAddHTML(e)}`,
   `<button class="btn" data-close>Close</button><button class="btn primary" id="dl-open">Open in The Grind</button>`,()=>{$("#dl-open").onclick=()=>{closeModal();go("grind");};});}
function openCalSync(){const u=me();const all=calItems(u).filter(e=>e.date>=iso(new Date(TODAY.getTime()-30*864e5)));
  modal("Sync to my calendar",`<p style="margin:0">Subscribe once and your Google, Outlook / Microsoft 365 or Apple calendar keeps itself up to date with the portal: company events for your role and province, plus your own Grind and Grow deadlines. Calendar apps refresh subscriptions every few hours.</p>
   <div id="cs-box" class="notice" style="margin:0">Getting your personal calendar address…</div>
   <hr style="border:0;border-top:1px solid var(--line);margin:4px 0"><p style="margin:0"><b>Just want a one-time copy?</b> <button class="btn sm" id="cs-ics">Download ${all.length} upcoming item${all.length===1?"":"s"} (.ics)</button></p>`,
   `<button class="btn ghost" id="cs-reset" title="Makes a new address; the old one stops working">Reset address</button><span style="flex:1"></span><button class="btn primary" data-close>Done</button>`,()=>{
   $("#cs-ics").onclick=()=>icsDownload(all,"icg-portal-calendar.ics","ICG Portal");
   const show=r=>{const web=r.url.replace(/^https:/,"webcal:");
     $("#cs-box").outerHTML=`<div id="cs-box" style="display:grid;gap:10px">
      <div class="cal-add"><a class="btn" href="https://calendar.google.com/calendar/r?cid=${encodeURIComponent(web)}" target="_blank" rel="noopener">Add to Google Calendar</a><a class="btn" href="https://outlook.office.com/calendar/addfromweb?url=${encodeURIComponent(r.url)}&name=${encodeURIComponent("ICG Portal")}" target="_blank" rel="noopener">Add to Outlook / M365</a><a class="btn" href="${esc(web)}">Add to Apple Calendar</a></div>
      <div class="field" style="margin:0"><label for="cs-url">Or copy your calendar address into any calendar app (“Subscribe” / “From internet”)</label><div class="row" style="flex-wrap:nowrap"><input id="cs-url" class="input" readonly value="${esc(r.url)}" style="flex:1"><button class="btn sm" id="cs-copy">Copy</button></div>
      <small class="muted">Keep this address private: anyone with it can see your calendar items. Use Reset address if it's been shared.</small></div></div>`;
     $("#cs-copy").onclick=async()=>{try{await navigator.clipboard.writeText(r.url);toast("Copied.");}catch(e){$("#cs-url").select();}};};
   const fail=e=>{$("#cs-box").textContent="Couldn't create your calendar address ("+(e.code||e.message)+"). You can still download a one-time copy below.";};
   if(DB.calFeed)DB.calFeed(false).then(show,fail);else fail(new Error("not available"));
   $("#cs-reset").onclick=()=>{if(!confirm("Make a new calendar address? Calendars subscribed with the old one stop updating."))return;DB.calFeed(true).then(r=>{show(r);toast("New address made. Subscribe again with it.");},fail);};});}
document.addEventListener("click",async e=>{const t=e.target;const u=me();if(!u||u.role!=="super")return;
  if(t.closest("[data-slacktoken]")){const v=($("#slack-token")||{}).value||"";if(!/^xox[bp]-/.test(v.trim())){toast("Paste the Bot User OAuth Token (starts with xoxb-).");return;}
    try{await DB.setSlackToken(v);S.security.slackTokenSet=true;logA("Saved the Slack bot token");save();renderApp();toast("Slack token saved.");}catch(err){toast("Couldn't save the token ("+(err.code||err.message)+").");}return;}
  if(t.closest("[data-slacktest]")){if(!S.security.slackOn){toast("Turn on “Send Slack messages” and Save settings first.");return;}
    slackOnly("test",[u.email],"slack-test","Test from the ICG Retail Ops Portal",["If you can read this, Slack messages from the portal work. 🎉",`${location.origin}/#home`]);toast("Test queued. Check Slack in a few seconds, or Admin → Email delivery if it doesn't arrive.");}});
document.addEventListener("click",e=>{const t=e.target;
  const pdv=t.closest('[data-ev^="pd-"],[data-ev^="gt-"],[data-ev^="ga-"]');if(pdv&&me()){e.stopImmediatePropagation();e.preventDefault();const it=findCalItem(pdv.dataset.ev);if(it)openDeadlineModal(it);return;}
  const ic=t.closest("[data-calics]");if(ic&&me()){const it=findCalItem(ic.dataset.calics);if(it)icsDownload([it],(it.title.replace(/[^\w]+/g,"-").slice(0,40)||"event")+".ics",it.title);return;}
  if(t.closest("[data-calsync]")&&me()){openCalSync();return;}
},true);
function viewCalendar(u){
  const m=S.cm?new Date(S.cm[0],S.cm[1],1):new Date(TODAY.getFullYear(),TODAY.getMonth(),1);
  const start=new Date(m);start.setDate(1-m.getDay());
  const ev=calItems(u);const cells=[];
  if(!S.calFreshShown){S.calFreshShown=true;S.calFresh=calNew(u).map(e=>e.id);setTimeout(()=>markSeen("cal"),0);}
  const fresh=ev.filter(e=>(S.calFresh||[]).includes(e.id)).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||"").localeCompare(b.time||""));
  const total=Math.ceil((m.getDay()+new Date(m.getFullYear(),m.getMonth()+1,0).getDate())/7)*7;
  for(let i=0;i<total;i++){const d=new Date(start);d.setDate(start.getDate()+i);
    const k=iso(d);const list=ev.filter(e=>e.date===k).sort((a,b)=>a.time.localeCompare(b.time));
    cells.push(`<div class="day ${d.getMonth()!==m.getMonth()?"out":""} ${k===iso(TODAY)?"today":""} ${has(u,"calendar")?"can-add":""}" data-day="${k}"><span class="dnum">${d.getDate()}</span>${list.map(e=>`<button class="ev t-${e.type}${(S.calFresh||[]).includes(e.id)?" ev-new":""}${e.mine?" ev-mine":""}" data-ev="${e.id}" title="${esc(e.title)}${e.mine?" (your "+esc(e.src)+" deadline)":""}"><span>${(S.calFresh||[]).includes(e.id)?'<b class="newdot">NEW</b> ':""}${e.mine?"📌 ":""}${e.task&&lvl(u)<=2&&["on","late"].includes(taskStatus(e,u.store))?"✓ ":""}${e.time?fmtTime(e.time).replace(":00","")+" ":""}${esc(e.title)}</span></button>`).join("")}</div>`);
  }
  return `<div class="page-head hello page-hero"><div class="hello-main">${logoHTML(curBrand(),"hello-logo")}<div><div class="eyebrow">${esc(curBrand().name)} · Calendar</div><h2><span class="hl">Calendar</span></h2><p>${has(u,"calendar")?"Click any day to add an event or reminder.":"Company events, deadlines and training for your role."} 📌 marks your own Grind and Grow deadlines.</p></div></div><div class="row"><button class="btn" data-calsync>Sync to my calendar</button>${has(u,"calendar")?'<button class="btn primary" data-newev>Add event</button>':""}</div></div>
  ${fresh.length?`<section class="card"><div class="card-h"><h3>New since your last visit</h3><span class="muted" style="font-size:13px">${fresh.length} added</span></div><div class="card-b"><div class="dmini">${fresh.map(e=>`<div class="srmini" data-ev="${e.id}" role="button" tabindex="0"><span class="bdot">${esc(e.title)}</span><span class="muted">${esc(fmtDate(e.date))}${e.time?" · "+esc(fmtTime(e.time)):""}</span><span class="st st-plain">${esc(e.type)}</span></div>`).join("")}</div></div></section>`:""}
  <section class="card"><div class="card-b" style="display:grid;gap:12px">
    <div class="cal-head"><button class="btn sm" data-cm="-1" aria-label="Previous month">‹</button><h3>${m.toLocaleDateString("en-CA",{month:"long",year:"numeric"})}</h3><button class="btn sm" data-cm="1" aria-label="Next month">›</button><button class="btn sm ghost" data-cm="0">Today</button><span style="flex:1"></span>
      <div class="legend"><span class="t-event"><i></i><span style="color:var(--ink-2)">Event</span></span><span class="t-reminder"><i></i><span style="color:var(--ink-2)">Reminder</span></span><span class="t-deadline"><i></i><span style="color:var(--ink-2)">Deadline</span></span><span class="t-training"><i></i><span style="color:var(--ink-2)">Training</span></span><span class="t-holiday"><i></i><span style="color:var(--ink-2)">Holiday</span></span></div></div>
    <div class="cal">${["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(d=>`<div class="dow">${d}</div>`).join("")}${cells.join("")}</div>
  </div></section>`;
}
function viewResources(u){
  const q=(S.q||"").toLowerCase();const favs=favsOf(u);
  const vis=visibleLinks(u).filter(l=>!q||l.name.toLowerCase().includes(q)||l.cat.toLowerCase().includes(q));
  const cats=[...new Set(S.links.map(l=>l.cat))];
  const hidden=S.links.length-visibleLinks(u).length;const rtab=S.resTab||"links";const sopRead=sopsFor(u).filter(s=>!s.archived&&sopNeedsRead(u,s)).length;
  const rtabs=`<div class="tabs" role="tablist"><button role="tab" data-restab="links" aria-selected="${rtab==="links"}">Links</button><button role="tab" data-restab="sops" aria-selected="${rtab==="sops"}">SOPs${sopRead?` <span class="count-pill">${sopRead}</span>`:""}</button></div>`;
  if(rtab==="sops")return `<div class="page-head hello page-hero"><div class="hello-main">${logoHTML(curBrand(),"hello-logo")}<div><div class="eyebrow">${esc(curBrand().name)} · Resources</div><h2><span class="hl">SOPs</span></h2><p>Standard operating procedures${lvl(u)<3?" for "+esc(u.store.replace(/ - /," ")):""}. Always use the current version here.</p></div></div></div>${rtabs}${viewSops(u)}`;
  return `<div class="page-head hello page-hero"><div class="hello-main">${logoHTML(curBrand(),"hello-logo")}<div><div class="eyebrow">${esc(curBrand().name)} · Resources</div><h2><span class="hl">Resources</span></h2><p>${visibleLinks(u).length} links for ${ROLES[u.role].label}s${lvl(u)<3?" in "+u.prov:""}. Star a link to add it to your dashboard.</p></div></div>
    <div class="row"><label for="rq" class="hidden">Filter resources</label><input id="rq" class="input" placeholder="Filter resources" value="${esc(S.q||"")}" style="width:240px">${has(u,"links")?'<button class="btn" data-admin-tab="links">Manage links</button>':""}</div></div>
  ${rtabs}
  ${hidden&&lvl(u)<4?`<p class="muted" style="margin:0;font-size:13px">${hidden} restricted or other-province links are hidden for your role.</p>`:""}
  <div class="res-grid">${cats.map(c=>{const ls=vis.filter(l=>l.cat===c);if(!ls.length)return "";return `<section class="res-cat card"><div class="card-b"><h3>${esc(c)}</h3><div class="res-list">${ls.map(l=>{const [ci,t]=kindIco(l.kind);const on=favs.includes(l.name);return `<div class="res"><span class="ico ${ci}">${t}</span><a href="${esc(l.url||"#")}" target="_blank" rel="noopener" data-link="${l.id}">${esc(l.name)}</a>${l.prov!=="All"?`<span class="chip">${l.prov}</span>`:""}${l.min>=3?'<span class="lock" title="Support Centre and above">SC</span>':""}<button class="star" data-fav="${esc(l.name)}" aria-pressed="${on}" aria-label="${on?"Remove from":"Add to"} quick links">${on?"★":"☆"}</button></div>`;}).join("")}</div></div></section>`;}).join("")||'<div class="empty">No resources match that filter.</div>'}</div>`;
}

/* ---------------- SOP library (Resources → SOPs) ----------------
   sops/{id}: {id,no,title,dept,summary,owner,audience,where,expires,archived,created,updated,
               versions:[{v,label,file:{id,path,name,size,type},at,by,note,postId}], notified:{soon,exp}}
   Each published version can announce itself as a required-reading Grind post to the same audience;
   acknowledging that post (in The Grind or on the SOP page) is the read record for that version. */
const SOP_DEPTS=["Store Operations","Cash & Safe","Compliance","Inventory & Receiving","Customer Service","Facilities","IT & POS","Security & Loss Prevention","People & HR","Marketing","Health & Safety"];
const canSop=u=>has(u,"links");
const fmtDateY=d=>pd(d).toLocaleDateString("en-CA",{month:"short",day:"numeric",year:"numeric"});
const sopCur=s=>(s.versions||[])[(s.versions||[]).length-1]||null;
const sopPost=s=>{const c=sopCur(s);return c&&c.postId?S.posts.find(p=>p.id===c.postId):null;};
function sopState(s){if(s.archived)return "archived";if(!s.expires)return "ok";const d=pd(s.expires);if(d<TODAY)return "expired";const soon=new Date(TODAY);soon.setDate(soon.getDate()+30);return d<=soon?"soon":"ok";}
function sopPill(s){const st=sopState(s);return st==="expired"?'<span class="st st-crit">Expired · under review</span>':st==="soon"?`<span class="st st-warn">Review by ${fmtDateY(s.expires)}</span>`:st==="archived"?'<span class="st st-plain">Archived</span>':s.expires?`<span class="st st-plain">Review by ${fmtDateY(s.expires)}</span>`:'<span class="muted">No expiry</span>';}
function sopsFor(u){return (S.sops||[]).filter(s=>(canSop(u)||!s.archived)&&seesAudience(u,s));}
function sopNeedsRead(u,s){const p=sopPost(s);return !!(p&&p.required&&!(p.acks||[]).includes(u.id)&&targetsFor(p,[u]).length);}
function sopReadPill(u,s){const p=sopPost(s);if(!p||!p.required)return '<span class="muted">—</span>';if((p.acks||[]).includes(u.id))return '<span class="st st-good">✓ Read</span>';return targetsFor(p,[u]).length?'<span class="st st-warn">Please read</span>':'<span class="muted">Not required</span>';}
function nextSopNo(){const n=(S.sops||[]).map(s=>+(String(s.no||"").match(/(\d+)$/)||[0,0])[1]).reduce((a,b)=>Math.max(a,b),0)+1;return "SOP-"+String(n).padStart(3,"0");}
function nextLabel(s){const c=sopCur(s);if(!c)return "1.0";const m=String(c.label||"").match(/^(\d+)(?:\.(\d+))?$/);return m?(+m[1]+1)+".0":String((s.versions||[]).length+1)+".0";}

function viewSops(u){
  if(S.sop){const s=(S.sops||[]).find(x=>x.id===S.sop);if(s&&(canSop(u)||seesAudience(u,s)))return viewSop(u,s);S.sop=null;}
  const F=S.sopf||(S.sopf={q:"",dept:"",show:"current"});const all=sopsFor(u);const q=F.q.toLowerCase();
  const depts=[...new Set(all.filter(s=>!s.archived).map(s=>s.dept))].sort();
  const toRead=all.filter(s=>!s.archived&&sopNeedsRead(u,s));const review=all.filter(s=>["expired","soon"].includes(sopState(s)));
  const L=all.filter(s=>F.show==="archived"?s.archived:F.show==="review"?["expired","soon"].includes(sopState(s)):F.show==="toread"?(!s.archived&&sopNeedsRead(u,s)):!s.archived)
    .filter(s=>(!F.dept||s.dept===F.dept)&&(!q||[s.no,s.title,s.dept,s.summary].join(" ").toLowerCase().includes(q)))
    .sort((a,b)=>String(a.dept).localeCompare(String(b.dept))||String(a.no).localeCompare(String(b.no)));
  const shows=[["current","All SOPs"],["toread",`To read (${toRead.length})`]].concat(canSop(u)?[["review",`Needs review (${review.length})`],["archived","Archived"]]:[]);
  return `<div class="card filters"><div class="card-b row"><div class="seg" role="radiogroup" aria-label="Show">${shows.map(([k,l])=>`<label class="seg-o"><input type="radio" name="sopshow" value="${k}" ${F.show===k?"checked":""}><span>${l}</span></label>`).join("")}</div>
    <label for="sop-q" class="hidden">Search SOPs</label><input id="sop-q" class="input" placeholder="Search SOPs" value="${esc(F.q)}" style="width:220px">
    <label for="sop-dept" class="hidden">Department</label><select id="sop-dept" class="input" style="width:auto"><option value="">All departments</option>${depts.map(d=>`<option ${F.dept===d?"selected":""}>${esc(d)}</option>`).join("")}</select>
    <span style="flex:1"></span>${canSop(u)?'<button class="btn primary" data-sopnew>Add SOP</button>':""}</div></div>
  <section class="card"><div class="card-b" style="overflow:auto">${L.length?`<div class="table-wrap"><table class="srt"><thead><tr><th>SOP</th><th>Department</th><th>Version</th><th>Updated</th><th>Review</th><th>You</th></tr></thead><tbody>${L.map(s=>{const c=sopCur(s)||{};return `<tr class="srrow" data-sop="${s.id}" tabindex="0"><td style="white-space:normal;min-width:240px"><span class="tkno">${esc(s.no||"")}</span> <b style="font-weight:600">${esc(s.title)}</b>${s.summary?`<small class="muted" style="display:block;font-size:12px">${esc(s.summary.slice(0,110))}${s.summary.length>110?"…":""}</small>`:""}</td><td>${esc(s.dept||"")}</td><td>v${esc(c.label||"")}</td><td style="white-space:nowrap">${c.at?fmtDT(c.at):""}</td><td>${sopPill(s)}</td><td>${sopReadPill(u,s)}</td></tr>`;}).join("")}</tbody></table></div>`:`<div class="empty">${F.show==="toread"?"Nothing to read. You are up to date.":F.show==="review"?"No SOPs are expired or due for review in the next 30 days.":(S.sops||[]).length?"No SOPs match.":canSop(u)?"No SOPs yet. Click Add SOP to upload the first one.":"No SOPs have been published for you yet."}</div>`}</div></section>`;
}

function viewSop(u,s){const c=sopCur(s)||{};const p=sopPost(s);const adm=canSop(u);const st=sopState(s);
  const kv=(k,v)=>`<div class="setting" style="padding:6px 0"><span class="muted">${k}</span><span style="text-align:right">${v}</span></div>`;
  const tg=p?targetsFor(p):[];const acked=p?tg.filter(x=>(p.acks||[]).includes(x.id)):[];const missing=p?tg.filter(x=>!(p.acks||[]).includes(x.id)):[];
  return `<div class="page-head" style="margin-bottom:8px"><button class="btn ghost" data-sopback>← All SOPs</button></div>
  ${st==="expired"?`<p class="notice" style="margin:0 0 12px">This SOP passed its review date (${fmtDateY(s.expires)}) and is under review. Keep following it until a new version is published.</p>`:""}
  <section class="card"><div class="card-b" style="display:grid;gap:8px"><div class="row"><span class="tkno">${esc(s.no||"")}</span><span class="chip">${esc(s.dept||"")}</span><span class="chip">v${esc(c.label||"")}</span>${sopPill(s)}</div>
   <h2 style="font-size:26px;margin:0">${esc(s.title)}</h2>${s.summary?`<p style="margin:0;white-space:pre-line">${esc(s.summary)}</p>`:""}
   <div class="row" style="margin-top:6px">${c.file?`<button class="btn primary" data-sopopen="${s.id}">Open SOP (${esc(extOf(c.file.name))})</button>`:""}${sopNeedsRead(u,s)&&p?`<button class="btn" data-ack="${p.id}">I've read this version</button>`:p&&(p.acks||[]).includes(u.id)?'<span class="ack">✓ You read this version</span>':""}
   ${adm?`<span style="flex:1"></span><button class="btn" data-sopver="${s.id}">Upload new version</button><button class="btn" data-sopedit="${s.id}">Edit details</button><button class="btn ghost" data-soparch="${s.id}">${s.archived?"Restore":"Archive"}</button>`:""}</div></div></section>
  <div class="rgrid" style="margin-top:16px"><div class="stack">
   <section class="card"><div class="card-h"><h3>Details</h3></div><div class="card-b">${kv("Current version","v"+esc(c.label||"")+(c.at?" · published "+fmtDT(c.at):""))}${kv("Published by",esc(c.by?userById(c.by).name:"—"))}${kv("Owner",esc(s.owner?userById(s.owner).name:"—"))}${kv("Review / expiry",s.expires?fmtDateY(s.expires):"None")}${kv("Applies to",esc(audLabel(s.audience))+" · "+esc(whereLabel(whereOf(s))))}${c.note?kv("What changed",esc(c.note)):""}</div></section>
   ${adm&&p&&p.required?`<section class="card"><div class="card-h"><h3>Read by</h3><span class="muted" style="font-size:13px">${acked.length} of ${tg.length} for v${esc(c.label||"")}</span></div><div class="card-b">${missing.length?`<details><summary>${missing.length} still to read</summary><div class="log" style="max-height:260px;overflow:auto">${missing.sort((a,b)=>String(a.store).localeCompare(String(b.store))||a.name.localeCompare(b.name)).map(x=>`<div><span><b>${esc(x.name)}</b> · ${esc(ROLES[x.role].label)} · ${esc(x.store||"")}</span></div>`).join("")}</div></details>`:'<p class="muted" style="margin:0">Everyone it applies to has read this version.</p>'}</div></section>`:""}
  </div><div class="stack">
   ${adm?`<section class="card"><div class="card-h"><h3>Version history</h3></div><div class="card-b"><ul class="tline">${(s.versions||[]).slice().reverse().map((v,i)=>`<li class="tl"><span class="tl-ic">${i===0?"●":"○"}</span><div><b>v${esc(v.label)}</b>${i===0?" (current)":""} · ${esc(userById(v.by).name)}${v.note?`<p class="tl-txt">${esc(v.note)}</p>`:""}<time>${fmtDT(v.at)}</time>${v.file?` <button class="btn sm ghost" data-sopfile="${s.id}|${esc(v.v)}">Open ${esc(extOf(v.file.name))}</button>`:""}</div></li>`).join("")}</ul></div></section>`:""}
  </div></div>`;}

/* Audience picker shared by the SOP form (same targeting as Grind posts). */
function audPickerHTML(D){const w=D.where,on=v=>w.vals.map(String).includes(String(v));
  const modes=[["all","All stores"],["prov","Regions (provinces)"],["brand","Brands"],["district","Districts"],["stores","Pick stores"]];
  let pick;
  if(w.mode==="all")pick='<p class="muted" style="margin:0;font-size:13px">Every store (limited by the roles above).</p>';
  else if(w.mode==="prov")pick=`<div class="checks">${["BC","AB","SK","ON"].map(x=>`<label><input type="checkbox" data-swv="${x}" ${on(x)?"checked":""}> ${x}</label>`).join("")}</div>`;
  else if(w.mode==="brand")pick=`<div class="checks">${S.brands.filter(b=>S.fleet.some(f=>f.brand===b.id)).map(b=>`<label><input type="checkbox" data-swv="${b.id}" ${on(b.id)?"checked":""}> <i class="bsq" style="background:${b.rail}"></i> ${esc(b.name)}</label>`).join("")}</div>`;
  else if(w.mode==="district")pick=`<div class="checks">${dmUsers().map(d=>`<label><input type="checkbox" data-swv="${d.id}" ${on(d.id)?"checked":""}> ${esc(d.name)}</label>`).join("")}<label><input type="checkbox" data-swv="none" ${on("none")?"checked":""}> Unassigned stores</label></div>`;
  else pick=`<div class="dbody" style="max-height:200px">${S.fleet.slice().sort((a,b)=>a.no-b.no).map(f=>`<label class="dopt"><input type="checkbox" data-swv="${f.no}" ${on(f.no)?"checked":""}><span><b>#${f.no}</b> ${esc(f.name)}</span></label>`).join("")}</div>`;
  return `<div class="field"><span class="flabel">Who it applies to (roles)</span><div class="checks">${Object.entries(AUD).map(([k,v])=>`<label><input type="checkbox" name="saud" value="${k}" ${D.aud.includes(k)?"checked":""}> ${v}</label>`).join("")}</div></div>
   <div class="field"><span class="flabel">Where</span><div class="seg" role="radiogroup" aria-label="Where">${modes.map(([k,l])=>`<label class="seg-o"><input type="radio" name="swmode" value="${k}" ${w.mode===k?"checked":""}><span>${l}</span></label>`).join("")}</div></div><div id="sop-pick">${pick}</div>`;}

function openSopModal(s,newVersion){const u=me();const isNew=!s;
  const D={aud:(s&&s.audience)||["all"],where:JSON.parse(JSON.stringify((s&&whereOf(s))||{mode:"all",vals:[]})),file:null,busy:false};
  const deptOpts=[...new Set(SOP_DEPTS.concat((S.sops||[]).map(x=>x.dept).filter(Boolean)))];
  const owners=S.users.filter(x=>x.status==="active"&&!x.gen&&lvl(x)>=3).sort((a,b)=>a.name.localeCompare(b.name));
  const showMeta=isNew||!newVersion,showFile=isNew||newVersion;
  const body=`${showMeta?`<div class="pm-sec"><h4>SOP</h4>
    <div class="grid2"><div class="field"><label for="sp-title">Title</label><input id="sp-title" class="input" value="${esc(s?s.title:"")}" maxlength="140" placeholder="e.g. Opening the store"></div><div class="field"><label for="sp-no">SOP number</label><input id="sp-no" class="input" value="${esc(s?s.no:nextSopNo())}" maxlength="20"></div></div>
    <div class="grid2"><div class="field"><label for="sp-dept">Department / category</label><select id="sp-dept" class="input">${deptOpts.map(d=>`<option ${(s?s.dept:"Store Operations")===d?"selected":""}>${esc(d)}</option>`).join("")}<option value="__new">+ New department…</option></select><input id="sp-dnew" class="input hidden" placeholder="New department name" style="margin-top:6px"></div>
     <div class="field"><label for="sp-owner">Owner <span class="muted" style="font-weight:400">(gets review reminders)</span></label><select id="sp-owner" class="input">${owners.map(x=>`<option value="${x.id}" ${((s&&s.owner)||u.id)===x.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select></div></div>
    <div class="field"><label for="sp-sum">Summary (optional)</label><textarea id="sp-sum" class="input" style="min-height:70px" placeholder="What this SOP covers">${esc(s?s.summary||"":"")}</textarea></div>
    <div class="grid2"><div class="field"><label for="sp-exp">Review / expiry date (optional)</label><input type="date" id="sp-exp" class="input" value="${esc(s?s.expires||"":"")}"><div class="row" style="gap:6px;margin-top:6px">${[[6,"6 months"],[12,"1 year"],[24,"2 years"]].map(([m,l])=>`<button class="btn sm ghost" data-spexp="${m}">${l}</button>`).join("")}<button class="btn sm ghost" data-spexp="0">None</button></div></div><div></div></div></div>
   <div class="pm-sec"><h4>Applies to</h4><div id="sop-aud">${audPickerHTML(D)}</div></div>`:""}
   ${showFile?`<div class="pm-sec"><h4>${isNew?"Document":"New version"}</h4>
    <div class="grid2"><div class="field"><label for="sp-ver">Version</label><input id="sp-ver" class="input" value="${esc(s?nextLabel(s):"1.0")}" maxlength="12"></div><div class="field"><span class="flabel">Published</span><p class="muted" style="margin:8px 0 0">Date and time are recorded automatically when you publish.</p></div></div>
    ${isNew?"":`<div class="field"><label for="sp-note">What changed</label><textarea id="sp-note" class="input" style="min-height:60px" placeholder="e.g. Updated cash count steps for Brinks pickups"></textarea></div>`}
    <div class="field"><span class="flabel">File</span><div class="drop" id="sp-drop"><input type="file" id="sp-file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.png,.jpg,.jpeg"><label for="sp-file"><b>Choose the SOP file</b> or drag it here · PDF or Office · up to 25 MB</label></div><div id="sp-fname" class="muted" style="font-size:13px"></div></div>
    ${has(u,"post")?`<label class="checks"><input type="checkbox" id="sp-ann" checked> Post to The Grind as required reading for everyone this applies to${isNew?"":" (they'll need to read the new version)"}</label>`:'<p class="muted" style="margin:0;font-size:13px">You don\'t have permission to post to The Grind, so this won\'t be announced.</p>'}</div>`:""}`;
  modal(isNew?"Add SOP":newVersion?"New version: "+esc(s.title):"Edit SOP details",body,`<span style="flex:1"></span><button class="btn" data-close>Cancel</button><button class="btn primary" id="sp-go">${isNew||newVersion?"Publish":"Save"}</button>`,root=>{
    root.querySelector(".modal").classList.add("wide");
    const audBind=()=>{const box=$("#sop-aud");if(!box)return;
      box.querySelectorAll('input[name="saud"]').forEach(i=>i.onchange=()=>{let a=[...box.querySelectorAll('input[name="saud"]:checked')].map(x=>x.value);if(i.value==="all"&&i.checked)a=["all"];else if(i.value!=="all")a=a.filter(x=>x!=="all");D.aud=a.length?a:["all"];box.innerHTML=audPickerHTML(D);audBind();});
      box.querySelectorAll('input[name="swmode"]').forEach(i=>i.onchange=()=>{D.where={mode:i.value,vals:[]};box.innerHTML=audPickerHTML(D);audBind();});
      box.querySelectorAll("[data-swv]").forEach(i=>i.onchange=()=>{const v=D.where.mode==="stores"?+i.dataset.swv:i.dataset.swv;D.where.vals=D.where.vals.filter(x=>String(x)!==String(v));if(i.checked)D.where.vals.push(v);});};
    audBind();
    const ds=$("#sp-dept");if(ds)ds.onchange=()=>$("#sp-dnew").classList.toggle("hidden",ds.value!=="__new");
    root.querySelectorAll("[data-spexp]").forEach(b=>b.onclick=e=>{e.preventDefault();const m=+b.dataset.spexp;if(!m){$("#sp-exp").value="";return;}const d=new Date(TODAY);d.setMonth(d.getMonth()+m);$("#sp-exp").value=iso(d);});
    const setF=f=>{if(!f)return;if(f.size>25*1048576){toast(`${f.name} is over 25 MB.`);return;}D.file=f;$("#sp-fname").textContent="✓ "+f.name+" · "+fmtSize(f.size);};
    const fi=$("#sp-file");if(fi){fi.onchange=e=>setF(e.target.files[0]);const dz=$("#sp-drop");["dragover","dragenter"].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add("over");}));["dragleave","drop"].forEach(ev=>dz.addEventListener(ev,()=>dz.classList.remove("over")));dz.addEventListener("drop",e=>{e.preventDefault();setF(e.dataTransfer.files[0]);});}
    $("#sp-go").onclick=async()=>{if(D.busy)return;
      const meta=showMeta?{title:$("#sp-title").value.trim(),no:$("#sp-no").value.trim(),dept:$("#sp-dept").value==="__new"?$("#sp-dnew").value.trim():$("#sp-dept").value,owner:$("#sp-owner").value,summary:$("#sp-sum").value.trim(),expires:$("#sp-exp").value,audience:D.aud,where:D.where}:{};
      if(showMeta&&(!meta.title||!meta.dept)){toast("Add a title and a department.");return;}
      if(showMeta&&meta.where.mode!=="all"&&!meta.where.vals.length){toast("Pick at least one "+{prov:"region",brand:"brand",district:"district",stores:"store"}[meta.where.mode]+", or choose All stores.");return;}
      if(showMeta&&meta.no&&(S.sops||[]).some(x=>x.no===meta.no&&(!s||x.id!==s.id))){toast(meta.no+" is already used by another SOP.");return;}
      if(showFile&&!D.file){toast("Choose the SOP file to upload.");return;}
      const label=showFile?($("#sp-ver").value.trim()||"1.0").replace(/^v/i,""):"";
      if(showFile&&s&&(s.versions||[]).some(v=>v.label===label)){toast("Version "+label+" already exists. Use a new version number.");return;}
      D.busy=true;$("#sp-go").disabled=true;$("#sp-go").textContent="Publishing…";
      try{const now=new Date().toISOString();
        if(isNew){s={id:"sop"+Date.now().toString(36)+Math.random().toString(36).slice(2,5),created:now,versions:[],archived:false,notified:{}};}
        if(showMeta){const oldExp=s.expires;Object.assign(s,meta);if(meta.expires!==oldExp)s.notified={};}
        let ver=null;
        if(showFile){const fid="f"+Date.now().toString(36)+Math.random().toString(36).slice(2,7);await FDB.put(fid,D.file);
          ver={v:String((s.versions||[]).length+1),label,file:{id:fid,name:D.file.name,size:D.file.size,type:D.file.type},at:now,by:u.id,note:isNew?"First version":($("#sp-note").value.trim()||"")};s.versions=(s.versions||[]).concat([ver]);}
        s.updated=now;
        if(ver&&$("#sp-ann")&&$("#sp-ann").checked){const p={id:"p"+Date.now(),kind:"sop",sopId:s.id,cat:"Ops",priority:"important",title:(isNew?"New SOP: ":"Updated SOP: ")+s.title+" (v"+label+")",
            body:[s.summary||"",isNew?"":(ver.note?"What changed: "+ver.note:""),"Please read it and click \"I've read this\". You'll also find it any time in Resources → SOPs."].filter(Boolean).join("\n\n"),
            audience:s.audience,where:s.where,prov:"All",pinned:false,required:true,pub:iso(TODAY),date:iso(TODAY),exp:"",due:"",attachments:[ver.file],author:u.id,acks:[]};
          const prev=(s.versions||[]).slice(0,-1).map(v=>v.postId&&S.posts.find(x=>x.id===v.postId)).filter(Boolean);
          prev.forEach(o=>{if(o.required||!o.exp||pd(o.exp)>=TODAY){o.required=false;const y=new Date(TODAY);y.setDate(y.getDate()-1);o.exp=iso(y);}});
          S.posts.push(p);ver.postId=p.id;}
        if(isNew)S.sops=(S.sops||[]).concat([s]);
        logA(isNew?`Added SOP ${s.no}: ${s.title} (v${label})`:ver?`Published ${s.no} v${label}: ${s.title}`:`Edited SOP details: ${s.no} ${s.title}`);
        save();closeModal();S.resTab="sops";S.sop=s.id;renderApp();toast(ver?(ver.postId?"Published and posted to The Grind.":"Published."):"Saved.");
      }catch(e){D.busy=false;$("#sp-go").disabled=false;$("#sp-go").textContent="Publish";}
    };
  });}

/* Review reminders: emailed to the owner when an SOP is 30 days from review and when it expires.
   Runs when someone who manages SOPs opens the portal (once per SOP per date). */
function sopReminders(){const u=me();if(!u||!canSop(u))return;let n=0;
  (S.sops||[]).forEach(s=>{const st=sopState(s);if(st!=="soon"&&st!=="expired")return;s.notified=s.notified||{};const k=st==="soon"?"soon":"exp";if(s.notified[k]===s.expires)return;
    const o=s.owner?userById(s.owner):null;if(!o||!o.email||o.name==="Unknown")return;
    DB.queueMail&&DB.queueMail({to:[o.email],ref:"sop:"+s.id,subject:st==="soon"?`SOP review due ${fmtDateY(s.expires)}: ${s.no} ${s.title}`:`SOP expired, needs review: ${s.no} ${s.title}`,
      text:[`Hi ${o.name.split(" ")[0]},`,"",st==="soon"?`${s.no} "${s.title}" is due for review on ${fmtDateY(s.expires)}.`:`${s.no} "${s.title}" passed its review date (${fmtDateY(s.expires)}). Staff now see it marked "Expired · under review".`,"","Review it and either upload a new version or set a new review date:",`${location.origin}/#resources`,"","Inspired Group Retail Ops Portal"].join("\n")});
    s.notified[k]=s.expires;n++;});
  if(n)save();}

document.addEventListener("click",e=>{const t=e.target;const u=me();if(!u)return;
  const r=t.closest("[data-sop]");if(r){S.sop=r.dataset.sop;renderApp();window.scrollTo(0,0);return;}
  if(t.closest("[data-sopback]")){S.sop=null;renderApp();return;}
  if(t.closest("[data-sopnew]")){openSopModal(null,false);return;}
  const g=t.closest("[data-sopgo]");if(g){closeModal();S.resTab="sops";S.sop=g.dataset.sopgo;S.view="resources";renderApp();window.scrollTo(0,0);return;}
  const rpt=t.closest("[data-reptab]");if(rpt){S.repTab=rpt.dataset.reptab;renderApp();return;}
  const rt=t.closest("[data-restab]");if(rt){S.resTab=rt.dataset.restab;S.sop=null;renderApp();return;}
  const op=t.closest("[data-sopopen]");if(op){const s=S.sops.find(x=>x.id===op.dataset.sopopen);const c=s&&sopCur(s);if(c&&c.file)openAttachment(c.file);return;}
  const of=t.closest("[data-sopfile]");if(of){const [id,v]=of.dataset.sopfile.split("|");const s=S.sops.find(x=>x.id===id);const ver=s&&s.versions.find(x=>x.v===v);if(ver&&ver.file)openAttachment(ver.file);return;}
  const ve=t.closest("[data-sopver]");if(ve){openSopModal(S.sops.find(x=>x.id===ve.dataset.sopver),true);return;}
  const ed=t.closest("[data-sopedit]");if(ed){openSopModal(S.sops.find(x=>x.id===ed.dataset.sopedit),false);return;}
  const ar=t.closest("[data-soparch]");if(ar){const s=S.sops.find(x=>x.id===ar.dataset.soparch);s.archived=!s.archived;s.updated=new Date().toISOString();logA((s.archived?"Archived":"Restored")+` SOP ${s.no}: ${s.title}`);save();renderApp();toast(s.archived?"Archived. Staff no longer see it.":"Restored.");return;}
});
document.addEventListener("keydown",e=>{const r=e.target.closest&&e.target.closest("[data-sop]");if(r&&e.key==="Enter"){S.sop=r.dataset.sop;renderApp();}});
document.addEventListener("change",e=>{const t=e.target;if(t.name==="sopshow"){(S.sopf=S.sopf||{q:"",dept:"",show:"current"}).show=t.value;renderApp();}if(t.id==="sop-dept"){S.sopf.dept=t.value;renderApp();}});
document.addEventListener("input",e=>{const t=e.target;if(t.id==="sop-q"){S.sopf.q=t.value;const pos=t.selectionStart;renderApp();const n=$("#sop-q");if(n){n.focus();n.setSelectionRange(pos,pos);}}});

/* ---------------- High Five (peer recognition) ----------------
   highfives/{id}: {id,date,by,byName,contact,toName,toEmail,manager,region,store,value,desc,anon,
                    notify,grind:"none"|"pending"|"approved"|"declined",postId,src,impHash,created}
   hfdraws/{YYYY-MM}: {id,month,entries,hfId,winner,winnerStore,sender,senderStore,senderAnon,at,by,
                       paid50,paid20,postId,history:[...]}
   Anyone can send one. Admins see everything in Admin → High Fives, approve Grind posts and run the
   monthly draw ($50 to a random recipient, one entry per High Five received; $20 to whoever sent it). */
const HF_VALUES=[["raise","Raise the Bar","They challenged the status quo and pursued excellence. They noticed what was needed, anticipated, and delivered."],
  ["people","People-Powered","When our people thrive, we all thrive. They collaborated with care and respect."],
  ["own","Own It","They stayed curious, tried new things, and found smarter ways to grow. They hold themselves with accountability and led with integrity."],
  ["wave","Ride the Wave","They were fluid, moved fast, and met the moment. They anticipated, adapted, and accelerated."],
  ["win","Win Together & Have Fun","They played to win, dreamt big, stayed grounded, and celebrated successes with others."]];
const hfVal=k=>(HF_VALUES.find(v=>v[0]===k)||[k,k||"—",""]);
const hfMonth=d=>String(d||"").slice(0,7);
const hfMonthLabel=m=>m?new Date(+m.slice(0,4),+m.slice(5,7)-1,1).toLocaleDateString("en-CA",{month:"long",year:"numeric"}):"";
/* "Manage High Fives" permission (Admin → Roles & permissions); on for Admins and P&C Admins by default. */
const hfAdmin=u=>has(u,"hf");
const hfRegions=()=>dmUsers().map(d=>d.name).concat(["Head Office"]);
function hfRegionFor(store){const f=fleetByName(store);const d=f&&f.dm?userById(f.dm):null;return d&&d.name!=="Unknown"?d.name:store===STORES[0]?"Head Office":"";}
const hfPending=()=>(S.highfives||[]).filter(h=>h.grind==="pending");
const hfMine=u=>(S.highfives||[]).filter(h=>h.toEmail&&h.toEmail===String(u.email||"").toLowerCase());

function openHighFiveModal(){const u=me();
  const people=S.users.filter(x=>x.status==="active"&&!x.gen&&x.id!==u.id);
  const vals=HF_VALUES.map(([k,l,d])=>`<label class="hf-val"><input type="radio" name="hfval" value="${k}"><span><b>${esc(l)}</b><small>${esc(d)}</small></span></label>`).join("");
  modal("Send a High Five 🙌",`
   <p class="notice" style="margin:0">Celebrate a teammate! Everyone who receives a High Five is entered into a monthly draw for a <b>$50 gift card</b> to their store. If the person you sent it to wins, you get a <b>$20 gift card</b> to your store too.</p>
   <div class="grid2"><div class="field"><span class="flabel">Date submitted</span><p style="margin:8px 0 0">${esc(fmtDateY(iso(TODAY)))}</p></div><div class="field"><span class="flabel">Submitted by</span><p style="margin:8px 0 0">${esc(u.name)}</p></div></div>
   <div class="grid2"><div class="field"><label for="hf-to">Teammate's first and last name *</label><input id="hf-to" class="input" list="hf-people" autocomplete="off" placeholder="Name of the teammate receiving a High Five"><datalist id="hf-people">${people.map(x=>`<option value="${esc(x.name)}">${esc(x.store||"")}</option>`).join("")}</datalist></div>
    <div class="field"><label for="hf-mgr">Employee's manager *</label><input id="hf-mgr" class="input" list="hf-mgrs" autocomplete="off" placeholder="Name of the employee's manager"><datalist id="hf-mgrs">${S.users.filter(x=>x.status==="active"&&!x.gen&&lvl(x)>=2).map(x=>`<option value="${esc(x.name)}">`).join("")}</datalist></div></div>
   <div class="grid2"><div class="field"><label for="hf-store">Location your teammate works at *</label><select id="hf-store" class="input"><option value="">Choose…</option>${STORES.map(s=>`<option>${esc(s)}</option>`).join("")}</select></div>
    <div class="field"><label for="hf-reg">Region (District Manager) *</label><select id="hf-reg" class="input"><option value="">Choose…</option>${hfRegions().map(r=>`<option>${esc(r)}</option>`).join("")}</select></div></div>
   <div class="field"><label for="hf-contact">Your contact information *</label><input id="hf-contact" class="input" value="${esc(u.email||"")}" placeholder="Your email address or phone number"></div>
   <div class="field"><span class="flabel">Company value displayed *</span><div class="hf-vals">${vals}</div></div>
   <div class="field"><label for="hf-desc">Description of the High Five *</label><textarea id="hf-desc" class="input" style="min-height:110px" placeholder="Describe the situation your teammate is receiving a High Five for"></textarea></div>
   <div class="field"><span class="flabel">Attach your name to this High Five? *</span><div class="seg" role="radiogroup" aria-label="Attach your name"><label class="seg-o"><input type="radio" name="hfanon" value="no" checked><span>Yes, show my name</span></label><label class="seg-o"><input type="radio" name="hfanon" value="yes"><span>No, send anonymously</span></label></div></div>
   <div class="pm-sec"><h4>Share it</h4>
    <label class="checks"><input type="checkbox" id="hf-send" checked> Email the High Five to my teammate</label>
    ${slackOn("hf")?`<label class="checks"><input type="checkbox" id="hf-slack" checked> Send it to them on Slack too</label>`:""}
    <div class="field" id="hf-emailrow"><label for="hf-email">Teammate's work email</label><input id="hf-email" class="input" type="email" placeholder="name@inspiredcannabis.ca"><small class="muted">Filled in for you when they're in the portal.</small></div>
    <label class="checks"><input type="checkbox" id="hf-grind"> Post it in The Grind so everyone can celebrate (an admin approves it first)</label>
    <label class="checks"><input type="checkbox" id="hf-copy"> Email me a copy of my responses</label></div>`,
   `<span style="flex:1"></span><button class="btn" data-close>Cancel</button><button class="btn primary" id="hf-go">Send High Five</button>`,root=>{
    root.querySelector(".modal").classList.add("wide");
    const fill=()=>{const n=$("#hf-to").value.trim().toLowerCase();const m=people.find(x=>x.name.toLowerCase()===n);if(!m)return;
      if(!$("#hf-email").value)$("#hf-email").value=m.email;if(!$("#hf-store").value&&STORES.includes(m.store)){$("#hf-store").value=m.store;$("#hf-store").onchange();}
      if(!$("#hf-mgr").value){const f=fleetByName(m.store);if(f&&f.mgr)$("#hf-mgr").value=f.mgr;}};
    $("#hf-to").addEventListener("change",fill);$("#hf-to").addEventListener("blur",fill);
    $("#hf-store").onchange=()=>{const r=hfRegionFor($("#hf-store").value);$("#hf-reg").value=r&&hfRegions().includes(r)?r:"";if(!$("#hf-mgr").value){const f=fleetByName($("#hf-store").value);if(f&&f.mgr)$("#hf-mgr").value=f.mgr;}};
    const slk=()=>!!($("#hf-slack")&&$("#hf-slack").checked);
    $("#hf-send").onchange=()=>$("#hf-emailrow").style.display=$("#hf-send").checked||slk()?"":"none";if($("#hf-slack"))$("#hf-slack").onchange=$("#hf-send").onchange;
    $("#hf-go").onclick=()=>{const g=id=>$("#"+id).value.trim();const val=(root.querySelector('input[name="hfval"]:checked')||{}).value;
      const d={toName:g("hf-to"),manager:g("hf-mgr"),store:$("#hf-store").value,region:$("#hf-reg").value,contact:g("hf-contact"),value:val,desc:g("hf-desc"),anon:root.querySelector('input[name="hfanon"]:checked').value==="yes"};
      const miss=[[!d.toName,"your teammate's name"],[!d.manager,"their manager"],[!d.store,"their location"],[!d.region,"the region"],[!d.contact,"your contact information"],[!d.value,"the company value"],[!d.desc,"a description"]].filter(x=>x[0]).map(x=>x[1]);
      if(miss.length){toast("Please add "+miss.join(", ")+".");return;}
      const send=$("#hf-send").checked,toSlack=slk(),email=g("hf-email").toLowerCase();
      if((send||toSlack)&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){toast("Add your teammate's work email (it's also how Slack finds them), or untick the email and Slack options.");return;}
      const now=new Date();const h=Object.assign({id:"hf"+now.getTime().toString(36)+Math.random().toString(36).slice(2,5),date:iso(TODAY),created:now.toISOString(),by:u.id,byName:u.name,
        toEmail:send||toSlack?email:"",notify:send,slack:toSlack,grind:$("#hf-grind").checked?"pending":"none",postId:"",src:"portal"},d);
      S.highfives=(S.highfives||[]).concat([h]);const v=hfVal(h.value)[1];const from=h.anon?"A teammate":u.name;
      if(send)DB.queueMail&&DB.queueMail({to:[email],ref:"hf:"+h.id,subject:`You got a High Five${h.anon?"":" from "+u.name}! 🙌`,
        text:[`Hi ${h.toName.split(" ")[0]},`,"",`${from} sent you a High Five for living our value "${v}":`,"",`"${h.desc}"`,"",`You're now entered in the ${hfMonthLabel(hfMonth(h.date))} High Five draw for a $50 gift card to your store. Keep it up!`,"","Inspired Group Retail Ops Portal"].join("\n")});
      if(toSlack)slackOnly("hf",[email],"hf:"+h.id,`🙌 You got a High Five${h.anon?"":" from "+u.name}!`,[`${from} sent you a High Five for living our value "${v}":`,"",`"${h.desc}"`,"",`You're entered in the ${hfMonthLabel(hfMonth(h.date))} draw for a $50 gift card to your store.`,`${location.origin}/#home`]);
      if($("#hf-copy").checked&&/@/.test(u.email||""))DB.queueMail&&DB.queueMail({to:[u.email],ref:"hf:"+h.id,subject:`Your High Five for ${h.toName}`,
        text:["Here's a copy of the High Five you sent:","",`Date submitted: ${fmtDateY(h.date)}`,`Submitted by: ${u.name}`,`Teammate: ${h.toName}`,`Manager: ${h.manager}`,`Contact: ${h.contact}`,`Region: ${h.region}`,`Location: ${h.store}`,`Company value: ${v}`,`Description: ${h.desc}`,`Attach your name: ${h.anon?"No (anonymous)":"Yes"}`,`Emailed to teammate: ${send?"Yes ("+email+")":"No"}`,`Post in The Grind: ${h.grind==="pending"?"Yes, waiting for admin approval":"No"}`,"","Inspired Group Retail Ops Portal"].join("\n")});
      logA(`Sent a High Five to ${h.toName} (${h.store})`);save();closeModal();renderApp();
      toast(`High Five sent to ${h.toName}! 🙌${h.grind==="pending"?" It'll appear in The Grind once an admin approves it.":""}`);};
  });}

/* --- Admin → High Fives --- */
function hfFiltered(){const F=S.hff||(S.hff={month:"12m",region:"",store:"",value:"",q:""});const since=new Date(TODAY);since.setMonth(since.getMonth()-12);
  return (S.highfives||[]).filter(h=>(F.month==="12m"?pd(h.date)>=since:F.month==="all"?true:hfMonth(h.date)===F.month)&&(!F.region||h.region===F.region)&&(!F.store||h.store===F.store)&&(!F.value||h.value===F.value)
    &&(!F.q||[h.toName,h.byName,h.store,h.desc,h.manager].join(" ").toLowerCase().includes(F.q.toLowerCase()))).sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.created||"").localeCompare(String(a.created||"")));}
const hfBars=(rows,max)=>rows.length?`<div class="hf-bars">${rows.map(([l,n,sub])=>`<div class="hf-bar"><span class="hf-bl" title="${esc(l)}">${esc(l)}${sub?`<small class="muted"> ${esc(sub)}</small>`:""}</span><span class="hf-bt"><i style="width:${max&&n?Math.max(3,Math.round(n/max*100)):0}%"></i></span><b>${n}</b></div>`).join("")}</div>`:'<p class="muted" style="margin:0">No High Fives in this view.</p>';
function viewHighFives(u){const F=S.hff||(S.hff={month:"12m",region:"",store:"",value:"",q:""});const L=hfFiltered();const all=S.highfives||[];
  const months=[...new Set(all.map(h=>hfMonth(h.date)).filter(Boolean))].sort().reverse();
  const cnt=(key)=>{const m={};L.forEach(h=>{const k=key(h);if(k)m[k]=(m[k]||0)+1;});return Object.entries(m).sort((a,b)=>b[1]-a[1]);};
  const byVal=HF_VALUES.map(([k,l])=>[l,L.filter(h=>h.value===k).length]);const vMax=Math.max(1,...byVal.map(x=>x[1]));
  const byStore=cnt(h=>h.store).slice(0,8);const byPerson=cnt(h=>h.toName&&(h.toName.trim()+"|"+(h.store||""))).slice(0,8).map(([k,n])=>{const [nm,st]=k.split("|");return [nm,n,st];});
  const trendM=[];for(let i=11;i>=0;i--){const d=new Date(TODAY.getFullYear(),TODAY.getMonth()-i,1);trendM.push(iso(d).slice(0,7));}
  const trend=trendM.map(m=>[m,all.filter(h=>hfMonth(h.date)===m).length]);const tMax=Math.max(1,...trend.map(x=>x[1]));
  const pend=hfPending();const draws=(S.hfdraws||[]).slice().sort((a,b)=>String(b.month).localeCompare(String(a.month)));
  const lastM=iso(new Date(TODAY.getFullYear(),TODAY.getMonth()-1,1)).slice(0,7);
  const sel=(id,cur,opts,any)=>`<select id="${id}" class="input" style="width:auto"><option value="">${any}</option>${opts.map(([v,l])=>`<option value="${esc(v)}" ${cur===v?"selected":""}>${esc(l)}</option>`).join("")}</select>`;
  return `<div class="card filters"><div class="card-b row">
    <select id="hff-month" class="input" style="width:auto"><option value="12m" ${F.month==="12m"?"selected":""}>Last 12 months</option><option value="all" ${F.month==="all"?"selected":""}>All time</option>${months.map(m=>`<option value="${m}" ${F.month===m?"selected":""}>${hfMonthLabel(m)}</option>`).join("")}</select>
    ${sel("hff-region",F.region,[...new Set(all.map(h=>h.region).filter(Boolean))].sort().map(x=>[x,x]),"All regions")}
    ${sel("hff-store",F.store,[...new Set(all.map(h=>h.store).filter(Boolean))].sort().map(x=>[x,x]),"All locations")}
    ${sel("hff-value",F.value,HF_VALUES.map(v=>[v[0],v[1]]),"All values")}
    <input id="hff-q" class="input" placeholder="Search names or text" value="${esc(F.q)}" style="width:200px"><span style="flex:1"></span>
    <button class="btn" data-hfcsv>Export CSV</button><button class="btn" data-hfimport>Import from Smartsheet</button><button class="btn primary" data-hfsend>Send a High Five</button></div></div>
  <div class="kpis"><div class="card kpi"><b>${L.length}</b><span>High Fives</span></div><div class="card kpi"><b>${new Set(L.map(h=>(h.toName||"").toLowerCase().trim()+"|"+h.store)).size}</b><span>Teammates celebrated</span></div><div class="card kpi"><b>${new Set(L.map(h=>(h.byName||"").toLowerCase().trim())).size}</b><span>People sending</span></div><div class="card kpi"><b style="color:${pend.length?"var(--warn)":"inherit"}">${pend.length}</b><span>Waiting for Grind approval</span></div></div>
  ${pend.length?`<section class="card"><div class="card-h"><h3>Waiting for approval to post in The Grind</h3></div><div class="card-b"><div class="dmini">${pend.map(h=>`<div class="srmini" style="align-items:flex-start"><span style="white-space:normal"><b>${esc(h.toName)}</b> · ${esc(h.store)} · ${esc(hfVal(h.value)[1])}<small class="muted" style="display:block">${esc(h.desc.slice(0,160))}${h.desc.length>160?"…":""}</small><small class="muted">From ${esc(h.byName)}${h.anon?" (anonymous to others)":""} · ${esc(fmtDateY(h.date))}</small></span><span class="row" style="flex-wrap:nowrap"><button class="btn sm primary" data-hfappr="${h.id}">Approve</button><button class="btn sm ghost danger" data-hfdecl="${h.id}">Decline</button></span></div>`).join("")}</div></div></section>`:""}
  <div class="rgrid"><div class="stack">
   <section class="card"><div class="card-h"><h3>By company value</h3></div><div class="card-b">${hfBars(byVal,vMax)}</div></section>
   <section class="card"><div class="card-h"><h3>Top locations</h3></div><div class="card-b">${hfBars(byStore,byStore.length?byStore[0][1]:1)}</div></section>
  </div><div class="stack">
   <section class="card"><div class="card-h"><h3>Last 12 months</h3></div><div class="card-b"><div class="hf-trend">${trend.map(([m,n])=>`<div title="${hfMonthLabel(m)}: ${n}"><i style="height:${Math.round(n/tMax*100)}%"></i><b>${n||""}</b><span>${new Date(+m.slice(0,4),+m.slice(5,7)-1,1).toLocaleDateString("en-CA",{month:"short"})}</span></div>`).join("")}</div></div></section>
   <section class="card"><div class="card-h"><h3>Most celebrated</h3></div><div class="card-b">${hfBars(byPerson,byPerson.length?byPerson[0][1]:1)}</div></section>
  </div></div>
  <section class="card"><div class="card-h"><h3>Monthly draw</h3><div class="row"><select id="hfd-month" class="input" style="width:auto">${trendM.slice().reverse().map(m=>`<option value="${m}" ${m===lastM?"selected":""}>${hfMonthLabel(m)} (${all.filter(h=>hfMonth(h.date)===m).length} entries)</option>`).join("")}</select><button class="btn primary" data-hfdraw>Run draw</button></div></div><div class="card-b">
   <p class="muted" style="margin:0 0 8px;font-size:13px">One entry per High Five received that month. The winner gets a $50 gift card to their store; whoever sent the winning High Five gets $20.</p>
   ${draws.length?`<div class="table-wrap"><table class="srt"><thead><tr><th>Month</th><th>Winner ($50)</th><th>Sent by ($20)</th><th>Entries</th><th>Gift cards</th><th></th></tr></thead><tbody>${draws.map(d=>`<tr><td>${esc(hfMonthLabel(d.month))}</td><td><b>${esc(d.winner)}</b><small class="muted" style="display:block">${esc(d.winnerStore||"")}</small></td><td>${esc(d.sender||"—")}${d.senderAnon?' <span class="chip">anonymous</span>':""}<small class="muted" style="display:block">${esc(d.senderStore||"")}</small></td><td>${d.entries}</td>
     <td><label class="checks nowrap"><input type="checkbox" data-hfpaid="${d.id}|paid50" ${d.paid50?"checked":""}> $50 given</label><label class="checks nowrap"><input type="checkbox" data-hfpaid="${d.id}|paid20" ${d.paid20?"checked":""}> $20 given</label></td>
     <td class="nowrap">${d.postId?'<span class="st st-good">Announced</span>':`<button class="btn sm" data-hfannounce="${d.id}">Announce in The Grind</button>`} <button class="btn sm ghost" data-hfredraw="${d.id}">Redraw</button></td></tr>`).join("")}</tbody></table></div>`:'<p class="muted" style="margin:0">No draws yet.</p>'}</div></section>
  <section class="card"><div class="card-h"><h3>High Fives</h3><span class="muted" style="font-size:13px">${L.length} shown</span></div><div class="card-b" style="overflow:auto">${L.length?`<div class="table-wrap"><table class="srt"><thead><tr><th>Date</th><th>Teammate</th><th>Location</th><th>Value</th><th>From</th><th>Shared</th></tr></thead><tbody>${L.slice(0,300).map(h=>`<tr class="srrow" data-hf="${h.id}" tabindex="0"><td class="nowrap">${esc(fmtDateY(h.date))}</td><td><b>${esc(h.toName)}</b><small class="muted" style="display:block">Manager: ${esc(h.manager||"—")}</small></td><td>${esc(h.store||"")}<small class="muted" style="display:block">${esc(h.region||"")}</small></td><td>${esc(hfVal(h.value)[1])}</td><td>${esc(h.byName||"")}${h.anon?' <span class="chip">anonymous</span>':""}</td><td>${[h.notify?"Emailed":"",h.grind==="approved"?"In The Grind":h.grind==="pending"?"Grind: waiting":h.grind==="declined"?"Grind: declined":"",h.src==="smartsheet"?"Imported":""].filter(Boolean).join(" · ")||"—"}</td></tr>`).join("")}</tbody></table></div>${L.length>300?`<p class="muted" style="font-size:13px">Showing the newest 300. Narrow the filters or export CSV for all.</p>`:""}`:'<p class="muted" style="margin:0">No High Fives match these filters.</p>'}</div></section>`;}

function openHfDetail(h){const v=hfVal(h.value);
  modal("High Five for "+esc(h.toName),`<div class="row"><span class="chip">${esc(v[1])}</span><span class="chip">${esc(fmtDateY(h.date))}</span>${h.anon?'<span class="chip">Anonymous to the recipient</span>':""}${h.src==="smartsheet"?'<span class="chip">Imported from Smartsheet</span>':""}</div>
   <p style="white-space:pre-line;margin:0">${esc(h.desc)}</p>
   <div>${[["Teammate",h.toName],["Manager",h.manager],["Location",h.store],["Region",h.region],["Submitted by",h.byName],["Contact",h.contact],["Emailed to",h.toEmail||"Not emailed"],["The Grind",{none:"Not requested",pending:"Waiting for approval",approved:"Posted",declined:"Declined"}[h.grind||"none"]]].map(([k,x])=>`<div class="setting" style="padding:6px 0"><span class="muted">${k}</span><span style="text-align:right">${esc(x||"—")}</span></div>`).join("")}</div>`,
   `<button class="btn ghost danger" data-hfdel="${h.id}">Delete</button><span style="flex:1"></span>${h.grind==="pending"?`<button class="btn" data-hfdecl="${h.id}">Decline post</button><button class="btn primary" data-hfappr="${h.id}">Approve post</button>`:`<button class="btn primary" data-close>Close</button>`}`);}

function hfApprove(h){const u=me();
  modal("Post this High Five in The Grind",`<p style="margin:0"><b>${esc(h.toName)}</b> · ${esc(h.store)} · ${esc(hfVal(h.value)[1])}</p><p style="margin:0;white-space:pre-line">${esc(h.desc)}</p>
   <div class="field"><span class="flabel">Who sees the post</span><div class="checks"><label><input type="radio" name="hfw" value="all" checked> Everyone</label><label><input type="radio" name="hfw" value="store"> ${esc(h.store)} only</label>${(fleetByName(h.store)||{}).prov?`<label><input type="radio" name="hfw" value="prov"> ${esc(fleetByName(h.store).prov)} stores</label>`:""}${(fleetByName(h.store)||{}).brand?`<label><input type="radio" name="hfw" value="brand"> ${esc((brandById(fleetByName(h.store).brand)||{name:""}).name)} stores</label>`:""}</div></div>
   <div class="field"><label for="hfa-body">Post text (you can edit it)</label><textarea id="hfa-body" class="input" style="min-height:120px">${esc(`${h.anon?"A teammate":h.byName} sent ${h.toName} a High Five for living our value "${hfVal(h.value)[1]}":\n\n"${h.desc}"`)}</textarea></div>`,
   `<span style="flex:1"></span><button class="btn" data-close>Cancel</button><button class="btn primary" id="hfa-go">Post it</button>`,root=>{
    $("#hfa-go").onclick=()=>{const w=root.querySelector('input[name="hfw"]:checked').value;const f=fleetByName(h.store)||{};
      const where=w==="store"&&f.no?{mode:"stores",vals:[f.no]}:w==="prov"?{mode:"prov",vals:[f.prov]}:w==="brand"?{mode:"brand",vals:[f.brand]}:{mode:"all",vals:[]};
      const p={id:"p"+Date.now(),kind:"highfive",hfId:h.id,cat:"People",priority:"normal",title:`🙌 High Five for ${h.toName}${h.store&&h.store!==STORES[0]?" ("+h.store.replace(/ - /," ")+")":""}`,body:$("#hfa-body").value.trim(),
        audience:["all"],where,prov:"All",pinned:false,required:false,pub:iso(TODAY),date:iso(TODAY),exp:"",due:"",attachments:[],author:u.id,byLabel:"High Five",acks:[]};
      S.posts.push(p);h.grind="approved";h.postId=p.id;logA(`Approved High Five post for ${h.toName}`);
      if(h.toEmail)slackOnly("hf",[h.toEmail],"hf:"+h.id,`🙌 You got a High Five${h.anon?"":" from "+h.byName}!`,[`For living our value "${hfVal(h.value)[1]}":`,"",`"${h.desc}"`,"","It's now on The Grind for everyone to see.",`${location.origin}/#grind`]);
      save();closeModal();renderApp();toast("Posted in The Grind.");};});}

function hfRunDraw(month,reason){const u=me();const entries=(S.highfives||[]).filter(h=>hfMonth(h.date)===month);
  if(!entries.length){toast("No High Fives in "+hfMonthLabel(month)+".");return;}
  const ex=(S.hfdraws||[]).find(d=>d.month===month);
  const pool=ex?entries.filter(h=>h.id!==ex.hfId):entries;if(!pool.length){toast("There's nobody else to draw.");return;}
  const r=new Uint32Array(1);crypto.getRandomValues(r);const w=pool[r[0]%pool.length];const sender=w.by?userById(w.by):null;
  const d={id:month,month,entries:entries.length,hfId:w.id,winner:w.toName,winnerStore:w.store,sender:w.byName||"",senderStore:sender&&sender.name!=="Unknown"?sender.store:"",senderAnon:!!w.anon,at:new Date().toISOString(),by:u.id,paid50:false,paid20:false,postId:"",
    history:ex?(ex.history||[]).concat([{winner:ex.winner,sender:ex.sender,at:ex.at,by:ex.by,reason:reason||""}]):[]};
  if(ex)Object.assign(ex,d);else S.hfdraws=(S.hfdraws||[]).concat([d]);
  logA(`High Five draw for ${hfMonthLabel(month)}: ${w.toName} (${w.store})${ex?" (redraw: "+(reason||"no reason")+")":""}`);save();renderApp();
  modal("🎉 "+esc(hfMonthLabel(month))+" winner",`<p style="margin:0;font-size:20px"><b>${esc(w.toName)}</b></p><p style="margin:0">${esc(w.store)} · wins a <b>$50 gift card</b></p><p style="margin:0">Sent by <b>${esc(w.byName||"—")}</b>${w.anon?" (sent anonymously)":""}${d.senderStore?" · "+esc(d.senderStore):""} · gets a <b>$20 gift card</b></p><p class="muted" style="margin:0">Picked at random from ${entries.length} entr${entries.length===1?"y":"ies"}.</p><blockquote style="margin:0;white-space:pre-line" class="muted">"${esc(w.desc)}"</blockquote>`,
    `<span style="flex:1"></span><button class="btn" data-close>Close</button><button class="btn primary" data-hfannounce="${d.id}">Announce in The Grind</button>`);}

function hfAnnounce(d){const u=me();closeModal();const h=(S.highfives||[]).find(x=>x.id===d.hfId)||{};
  const p={id:"p"+Date.now(),kind:"highfive",cat:"People",priority:"important",title:`🎉 ${hfMonthLabel(d.month)} High Five draw winner: ${d.winner}`,
    body:[`Congratulations ${d.winner}${d.winnerStore?" ("+d.winnerStore+")":""}! You've won a $50 gift card to your store.`,d.senderAnon?"The teammate who sent the winning High Five gets a $20 gift card too.":`${d.sender} sent the winning High Five and gets a $20 gift card too.`,h.desc?`The High Five${h.value?" ("+hfVal(h.value)[1]+")":""}: "${h.desc}"`:"",`There were ${d.entries} High Fives in ${hfMonthLabel(d.month)}. Keep celebrating each other!`].filter(Boolean).join("\n\n"),
    audience:["all"],where:{mode:"all",vals:[]},prov:"All",pinned:false,required:false,pub:iso(TODAY),date:iso(TODAY),exp:"",due:"",attachments:[],author:u.id,byLabel:"High Five",acks:[]};
  S.posts.push(p);d.postId=p.id;logA(`Announced ${hfMonthLabel(d.month)} High Five winner`);save();renderApp();toast("Winner announced in The Grind.");}

function hfCsv(){const L=hfFiltered();const q=v=>`"${String(v==null?"":v).replace(/"/g,'""')}"`;
  const rows=[["Date Submitted","Submitted By","Teammate","Employee's Manager","Contact","Region","Location","Company Value","Description","Anonymous","Emailed To","Grind","Source"]].concat(L.map(h=>[h.date,h.byName,h.toName,h.manager,h.contact,h.region,h.store,hfVal(h.value)[1],h.desc,h.anon?"Yes":"No",h.toEmail,h.grind,h.src]));
  const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([rows.map(r=>r.map(q).join(",")).join("\r\n")],{type:"text/csv"}));a.download="high-fives-"+iso(TODAY)+".csv";a.click();}

/* Smartsheet import: an Excel export of the High Five form's sheet. Columns are matched by header. */
function hfFromRows(rows,all){const since=new Date(TODAY);since.setMonth(since.getMonth()-12);const out=[];let old=0,blank=0;
  const pick=(r,...keys)=>{const k=Object.keys(r).find(c=>keys.some(x=>c.toLowerCase().replace(/[^a-z]/g,"").includes(x)));return k?r[k]:"";};
  const toDate=v=>{if(v instanceof Date)return iso(v);if(typeof v==="number"){const d=new Date(Math.round((v-25569)*864e5));return iso(new Date(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()));}const s=String(v||"").trim();let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return s.slice(0,10);m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);if(m){const y=+m[3]<100?2000+ +m[3]:+m[3];return iso(new Date(y,+m[1]-1,+m[2]));}const d=new Date(s);return isNaN(d)?"":iso(d);};
  rows.forEach(r=>{const toName=String(pick(r,"firstandlastname")||"").trim();const desc=String(pick(r,"description")||"").trim();if(!toName&&!desc){blank++;return;}
    const date=toDate(pick(r,"datesubmitted","created"));if(!date){blank++;return;}if(!all&&pd(date)<since){old++;return;}
    const vRaw=String(pick(r,"companyvalue")||"").toLowerCase();const vm=HF_VALUES.find(v=>vRaw.startsWith(v[1].toLowerCase().slice(0,6)))||HF_VALUES.find(v=>vRaw.includes(v[1].toLowerCase().split(" ")[0]));
    const attach=String(pick(r,"attachyourname")||"").trim().toLowerCase();const byName=String(pick(r,"submittedby")||"").trim();
    const store=String(pick(r,"location")||"").trim();const st=STORES.find(x=>x.toLowerCase()===store.toLowerCase())||store;
    const h={date,byName,by:(S.users.find(x=>x.name.toLowerCase()===byName.toLowerCase())||{}).id||"",contact:String(pick(r,"contactinformation")||"").trim(),toName,toEmail:"",manager:String(pick(r,"employeesmanager","manager")||"").trim(),
      region:String(pick(r,"region")||"").trim(),store:st,value:vm?vm[0]:"",desc,anon:attach.startsWith("n"),notify:false,grind:"none",postId:"",src:"smartsheet"};
    h.impHash=sgHash(JSON.stringify([h.date,h.byName,h.toName,h.desc]));h.id="hf-"+h.impHash;h.created=date+"T12:00:00.000Z";out.push(h);});
  return {list:out,old,blank};}
function openHfImport(){let rows=null,fileName="",all=false;
  const draw=()=>{const box=$("#hfi-res");if(!rows){box.innerHTML="";$("#hfi-go").disabled=true;return;}const r=hfFromRows(rows,all);const have=new Set((S.highfives||[]).map(h=>h.id));const nw=r.list.filter(h=>!have.has(h.id));
    box.innerHTML=`<div class="kpis" style="margin:0"><div class="card kpi"><b>${r.list.length}</b><span>High Fives in range</span></div><div class="card kpi"><b style="color:var(--good)">${nw.length}</b><span>New to the portal</span></div><div class="card kpi"><b style="color:var(--ink-3)">${r.list.length-nw.length}</b><span>Already imported</span></div></div><p class="muted" style="margin:0;font-size:13px">${esc(fileName)}: ${rows.length} rows. Left out: ${r.old} older than 12 months, ${r.blank} blank. Imported High Fives don't send emails or Grind posts.</p>`;
    $("#hfi-go").disabled=!nw.length;$("#hfi-go").textContent=`Import ${nw.length} High Fives`;};
  modal("Import High Fives from Smartsheet",`<p style="margin:0">Copies past submissions from the Smartsheet sheet behind the <b>Inspired High Five</b> form. Safe to run again: rows already imported are skipped.</p>
    <ol class="muted" style="margin:0;padding-left:18px;font-size:13px"><li>In Smartsheet, open the High Five submissions sheet → <b>File → Export → Export to Microsoft Excel</b>.</li><li>Choose that file below.</li></ol>
    <div class="field"><label for="hfi-file">Smartsheet export (.xlsx)</label><input id="hfi-file" type="file" accept=".xlsx,.xls" class="input"></div>
    <div class="field"><span class="flabel">Which rows</span><div class="checks"><label><input type="radio" name="hfimode" value="recent" checked> Last 12 months</label><label><input type="radio" name="hfimode" value="all"> Everything in the file</label></div></div><div id="hfi-res"></div>`,
    `<span style="flex:1"></span><button class="btn" data-close>Cancel</button><button class="btn primary" id="hfi-go" disabled>Import</button>`,root=>{
    $("#hfi-file").onchange=async e=>{const f=e.target.files[0];if(!f)return;fileName=f.name;try{await loadXLSX();const wb=XLSX.read(await f.arrayBuffer());const ws=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(ws,{defval:"",raw:true});}catch(err){rows=null;toast("Couldn't read that file.");}draw();};
    root.querySelectorAll('input[name="hfimode"]').forEach(x=>x.onchange=()=>{all=x.value==="all";draw();});
    $("#hfi-go").onclick=()=>{const r=hfFromRows(rows,all);const have=new Set((S.highfives||[]).map(h=>h.id));const nw=r.list.filter(h=>!have.has(h.id));S.highfives=(S.highfives||[]).concat(nw);
      logA(`Imported ${nw.length} High Fives from Smartsheet (${fileName})`);save();closeModal();renderApp();toast(`Imported ${nw.length} High Fives.`);};});}

document.addEventListener("click",e=>{const t=e.target;const u=me();if(!u)return;
  if(t.closest("[data-hfsend]")){openHighFiveModal();return;}
  const r=t.closest("[data-hf]");if(r){const h=S.highfives.find(x=>x.id===r.dataset.hf);if(h)openHfDetail(h);return;}
  const ap=t.closest("[data-hfappr]");if(ap){const h=S.highfives.find(x=>x.id===ap.dataset.hfappr);if(h)hfApprove(h);return;}
  const dc=t.closest("[data-hfdecl]");if(dc){const h=S.highfives.find(x=>x.id===dc.dataset.hfdecl);if(h){h.grind="declined";logA(`Declined High Five post for ${h.toName}`);save();closeModal();renderApp();toast("Declined. It won't be posted in The Grind.");}return;}
  const dl=t.closest("[data-hfdel]");if(dl){const h=S.highfives.find(x=>x.id===dl.dataset.hfdel);if(h&&confirm(`Delete the High Five for ${h.toName}? This can't be undone.`)){S.highfives=S.highfives.filter(x=>x!==h);logA(`Deleted High Five for ${h.toName}`);save();closeModal();renderApp();}return;}
  if(t.closest("[data-hfdraw]")){const m=$("#hfd-month").value;const ex=(S.hfdraws||[]).find(d=>d.month===m);if(ex){toast(`${hfMonthLabel(m)} was already drawn (${ex.winner}). Use Redraw on that row if you need to.`);return;}hfRunDraw(m);return;}
  const rd=t.closest("[data-hfredraw]");if(rd){const d=S.hfdraws.find(x=>x.id===rd.dataset.hfredraw);const why=prompt(`Redraw ${hfMonthLabel(d.month)}? ${d.winner} will be replaced. Reason (e.g. no longer with the company):`);if(why!==null)hfRunDraw(d.month,why.trim());return;}
  const an=t.closest("[data-hfannounce]");if(an){const d=S.hfdraws.find(x=>x.id===an.dataset.hfannounce);if(d&&!d.postId)hfAnnounce(d);else closeModal();return;}
  if(t.closest("[data-hfcsv]")){hfCsv();return;}
  if(t.closest("[data-hfimport]")){openHfImport();return;}
});
document.addEventListener("change",e=>{const t=e.target;const pd2=t.dataset&&t.dataset.hfpaid;if(pd2){const [id,k]=pd2.split("|");const d=S.hfdraws.find(x=>x.id===id);d[k]=t.checked;logA(`${hfMonthLabel(d.month)} High Five draw: ${k==="paid50"?"$50":"$20"} gift card ${t.checked?"given":"not given"}`);save();return;}
  const m={"hff-month":"month","hff-region":"region","hff-store":"store","hff-value":"value"}[t.id];if(m){S.hff[m]=t.value;renderApp();}});
document.addEventListener("input",e=>{const t=e.target;if(t.id==="hff-q"){S.hff.q=t.value;const pos=t.selectionStart;renderApp();const n=$("#hff-q");if(n){n.focus();n.setSelectionRange(pos,pos);}}});
document.addEventListener("keydown",e=>{const r=e.target.closest&&e.target.closest("[data-hf]");if(r&&e.key==="Enter"){const h=S.highfives.find(x=>x.id===r.dataset.hf);if(h)openHfDetail(h);}});

