const GROW_STAGES={REN:["Scoping","Quotes","Design","Approval","Permits","Scheduled","In progress","Punch list","Complete"],
  CONV:["Planning","Design & signage","Approval","Regulator & landlord","Ordering","Conversion","Relaunch","Post-conversion review","Complete"],NSO:["Site selection","LOI / lease","Design & permits","Construction","Licensing & inspection","Turnover & setup","Open","Post-open review","Complete"],
  NSA:["Prospect","LOI","Due diligence","Closing prep","Day 1 / takeover","Integration & conversion","Post-conversion review","Complete"]};
const GROW_MS={REN:[["Scope finalised",-60],["Quotes received",-45],["Design approved",-35],["Budget approved",-30],["Permits issued",-14],["Works start",-10],["Works complete",0],["Close-out complete",14]],
  CONV:[["Conversion approved",-60],["Designs & signage approved",-45],["Signage ordered",-30],["Regulator notified / approved",-21],["Signage installed",-1],["Relaunch day",0],["30-day review",30]],NSO:[["Lease signed",null],["Permits issued",null],["Construction start",null],["GC handover (construction complete)",-14],["Provincial inspection (LDB)",-12],["Licence issued",-9],["Retail turnover",-8],["Opening day",0],["30-day review",30]],
  NSA:[["LOI signed",null],["Due diligence complete",-14],["Licence transfer approved",-3],["Closing / Day 1",0],["POS conversion",35],["Post-conversion review",60]]};
