  if(rtab==="hf")return `<div class="page-head hello page-hero"><div class="hello-main">${logoHTML(curBrand(),"hello-logo")}<div><div class="eyebrow">${esc(curBrand().name)} · Reports</div><h2><span class="hl">High Fives</span></h2><p>Peer recognition across the company: who's being celebrated, for which values, and the monthly draw.</p></div></div></div>${rtabs}${viewHighFives(u)}`;
