const BULK_HEADS=["First name*","Last name*","Email*","Role*","Store number","Job title","Brand","District stores","Status"];
const BULK_EX=[["Alex","Rivera","alex.rivera@dutch.love","Store User","301","Budtender","","","Invited"],["Sam","Chen","sam.chen@imagine-cannabis.ca","Store Manager","205","Store Manager","","","Invited"],["Taylor","Morgan","taylor.morgan@inspiredcannabis.ca","District Manager","","District Manager","Inspired Group","600;601;602","Invited"]];
const EX_EMAILS=BULK_EX.map(r=>r[2]);
const bulkCSV=()=>[BULK_HEADS].concat(BULK_EX).map(r=>r.map(v=>/[",;\n]/.test(v)?`"${v.replace(/"/g,'""')}"`:v).join(",")).join("\n");
function parseDelimited(text){const delim=text.split("\n")[0].includes("\t")?"\t":",";const rows=[];let row=[],f="",q=false;
  for(let i=0;i<text.length;i++){const c=text[i];
    if(q){if(c==='"'){if(text[i+1]==='"'){f+='"';i++;}else q=false;}else f+=c;}
    else if(c==='"')q=true;else if(c===delim){row.push(f);f="";}else if(c==="\n"||c==="\r"){if(c==="\r"&&text[i+1]==="\n")i++;row.push(f);rows.push(row);row=[];f="";}else f+=c;}
  if(f||row.length){row.push(f);rows.push(row);}return rows;}
let XLSX_P=null;
function loadXLSX(){if(window.XLSX)return Promise.resolve();if(XLSX_P)return XLSX_P;XLSX_P=new Promise((res,rej)=>{const sc=document.createElement("script");sc.src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";sc.onload=res;sc.onerror=()=>{XLSX_P=null;rej(new Error("load"));};document.head.appendChild(sc);});return XLSX_P;}
const ROLE_BY_LABEL=Object.fromEntries(Object.entries(ROLES).flatMap(([k,r])=>[[r.label.toLowerCase(),k],[k,k]]).concat([["store user","store"],["user","store"],["dm","dm"],["head office user","ho"],["superadmin","super"]]));
function validateBulk(rows,u,opts){
  const norm=h=>String(h||"").toLowerCase().replace(/\*/g,"").replace(/\s+/g," ").trim();
  const head=(rows[0]||[]).map(norm);const need=["first name","last name","email","role"];
  const missing=need.filter(n=>!head.includes(n));if(missing.length)return {fatal:`The file is missing these columns: ${missing.map(m=>m.replace(/\b\w/g,c=>c.toUpperCase())).join(", ")}. Start from the template so the headers match.`};
  const col=n=>head.indexOf(n);const g=(r,n)=>{const i=col(n);return i<0?"":String(r[i]??"").trim();};
  const allowed=S.security.domains.split(/[,\s]+/).filter(Boolean).concat(...S.brands.map(b=>b.domains));
  const seen=new Set();const out=[];
  rows.slice(1).forEach((r,ix)=>{if(!r.some(v=>String(v??"").trim()))return;
    const R={line:ix+2,first:g(r,"first name"),last:g(r,"last name"),email:g(r,"email").toLowerCase(),roleIn:g(r,"role"),storeNo:g(r,"store number").replace(/\.0$/,""),title:g(r,"job title"),brandIn:g(r,"brand"),dist:g(r,"district stores"),statusIn:g(r,"status"),err:[],warn:[]};
    R.name=(R.first+" "+R.last).trim();
    if(EX_EMAILS.includes(R.email)){R.action="skip";R.warn.push("Example row from the template");out.push(R);return;}
    if(!R.first||!R.last)R.err.push("First and last name are required");
    if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(R.email))R.err.push("Email is missing or invalid");
    else if(!allowed.includes(domainOf(R.email)))R.err.push(`@${domainOf(R.email)} isn't an allowed domain`);
    R.role=ROLE_BY_LABEL[R.roleIn.toLowerCase()];
    if(!R.role)R.err.push(R.roleIn?`Unknown role "${R.roleIn}"`:"Role is required");
    else if(!can.assignable(u).includes(R.role))R.err.push(`You can't create ${ROLES[R.role].label} users`);
    if(R.role==="sm"||R.role==="store"){const f=S.fleet.find(x=>String(x.no)===R.storeNo);if(!R.storeNo)R.err.push("Store number is required for this role");else if(!f)R.err.push(`Store #${R.storeNo} isn't in the fleet`);else R.store=f.name;}
    else{R.store=STORES[0];if(R.storeNo)R.warn.push("Store number ignored for Head Office roles");}
    R.brand="auto";if(R.brandIn){const b=S.brands.find(b=>b.name.toLowerCase()===R.brandIn.toLowerCase()||b.id===R.brandIn.toLowerCase());if(b)R.brand=b.id;else R.err.push(`Unknown brand "${R.brandIn}"`);}
    else if(R.role&&lvl({role:R.role})>=3)R.brand="group";
    R.distNos=[];if(R.dist){if(R.role!=="dm")R.warn.push("District stores ignored (not a District Manager)");else R.dist.split(/[;,\s]+/).filter(Boolean).forEach(n=>{n=n.replace(/^#/,"");const f=S.fleet.find(x=>String(x.no)===n);if(!f)R.err.push(`District store #${n} isn't in the fleet`);else{R.distNos.push(f.no);const o=dmOf(f);if(o&&o.email!==R.email)R.warn.push(`#${f.no} moves from ${o.name}`);}});}
    R.status=/^active$/i.test(R.statusIn)?"active":"invited";if(R.statusIn&&!/^(active|invited)$/i.test(R.statusIn))R.warn.push(`Status "${R.statusIn}" read as Invited`);
    if(seen.has(R.email)&&R.email)R.err.push("Email appears more than once in this file");seen.add(R.email);
    const ex=S.users.find(x=>x.email.toLowerCase()===R.email);R.existing=ex||null;
    if(R.err.length)R.action="error";
    else if(ex){if(!opts.update){R.action="skip";R.warn.push("Already has an account");}else if(!can.manageUser(u,ex)){R.action="error";R.err.push("You can't change this existing account");}else R.action="update";}
    else R.action="create";
    out.push(R);});
  return {rows:out};
}
function openBulkModal(){
  const u=me();let parsed=null,fileName="",opts={update:false,invite:true};
  const pill=a=>({create:'<span class="st st-good">+ Create</span>',update:'<span class="st st-info">↻ Update</span>',skip:'<span class="st st-warn">– Skip</span>',error:'<span class="st st-crit">✕ Error</span>'})[a];
  const render=()=>{const box=$("#bulk-res");if(!parsed){box.innerHTML="";return;}
    if(parsed.fatal){box.innerHTML=`<div class="vault-warn">${esc(parsed.fatal)}</div>`;$("#bulk-go").disabled=true;return;}
    const v=validateBulk(parsed.data,u,opts);const c=k=>v.rows.filter(r=>r.action===k).length;const n=c("create")+c("update");
    box.innerHTML=`<div class="bulk-sum"><b>${esc(fileName)}</b> · ${v.rows.length} row${v.rows.length===1?"":"s"}: ${pill("create")} ${c("create")} ${pill("update")} ${c("update")} ${pill("skip")} ${c("skip")} ${pill("error")} ${c("error")}</div>
      ${c("error")?'<p class="muted" style="margin:0;font-size:13px">Rows with errors are left out. Fix them in the file and upload it again, or import the rest now.</p>':""}
      <div class="table-wrap bulk-tbl"><table><thead><tr><th>Row</th><th>Name</th><th>Email</th><th>Role</th><th>Store / district</th><th>Result</th></tr></thead><tbody>
      ${v.rows.map(r=>`<tr class="${r.action==="error"?"bad":""}"><td>${r.line}</td><td>${esc(r.name||"—")}</td><td>${esc(r.email||"—")}</td><td>${r.role?ROLES[r.role].label:esc(r.roleIn||"—")}</td><td style="white-space:normal">${r.role==="dm"?(r.distNos.length?r.distNos.map(x=>"#"+x).join(", "):"No stores yet"):esc(r.store||"—")}</td><td style="white-space:normal">${pill(r.action)}${r.err.concat(r.warn).length?`<small class="bulk-msg">${r.err.map(e=>`<span style="color:var(--crit)">${esc(e)}</span>`).concat(r.warn.map(esc)).join("<br>")}</small>`:""}</td></tr>`).join("")}</tbody></table></div>`;
    const go=$("#bulk-go");go.disabled=!n;go.textContent=n?`Import ${n} user${n===1?"":"s"}`:"Nothing to import";parsed.v=v;};
  modal("Bulk upload users",`
    <ol class="bulk-steps"><li><b>Get the template.</b> It has the right columns, dropdowns for role, brand and status, and a list of store numbers.
      <div class="row" style="margin-top:8px"><button class="btn sm" id="bulk-copy">Copy CSV template</button><span class="muted" style="font-size:12px">The Excel template (.xlsx) is attached in the chat for now; the live portal downloads it from here.</span></div>
      <details style="margin-top:8px"><summary style="cursor:pointer;font-size:13px">See the columns</summary><div class="table-wrap" style="margin-top:6px"><table><thead><tr>${BULK_HEADS.map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${BULK_EX.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>
      <p class="muted" style="font-size:12px;margin:6px 0 0">Store number is required for Store Users and Store Managers. District stores (separated by ;) is for District Managers only. Leave Brand blank to set it from the email domain.</p></details></li>
    <li><b>Upload the filled-in file</b> (.xlsx or .csv), or paste rows copied from Excel.
      <div class="drop" id="bulk-drop"><input type="file" id="bulk-file" accept=".csv,.xlsx,.xls,text/csv"><label for="bulk-file"><b>Choose a file</b> or drag it here</label></div>
      <details><summary style="cursor:pointer;font-size:13px">Paste instead</summary><label for="bulk-paste" class="hidden">Paste rows</label><textarea id="bulk-paste" class="input" placeholder="Paste the header row and your user rows from Excel" style="min-height:90px;margin-top:6px;font-family:ui-monospace,Menlo,monospace;font-size:12px"></textarea><button class="btn sm" id="bulk-pastego" style="margin-top:6px">Check pasted rows</button></details></li>
    <li><b>Review, then import.</b>
      <div class="checks" style="margin:6px 0"><label><input type="checkbox" id="bulk-upd"> Update users who already have an account (matched by email)</label><label><input type="checkbox" id="bulk-inv" checked> Email an invite to new users</label></div>
      <div id="bulk-res"><p class="muted" style="margin:0;font-size:13px">Nothing uploaded yet.</p></div></li></ol>`,
    `<button class="btn" data-close>Cancel</button><button class="btn primary" id="bulk-go" disabled>Import users</button>`,root=>{
      root.querySelector(".modal").classList.add("wide");
      $("#bulk-copy").onclick=()=>{try{navigator.clipboard.writeText(bulkCSV()).then(()=>toast("Template copied. Paste it into Excel or a text file and save as .csv."),()=>toast("Copy was blocked by the browser."));}catch(e){toast("Copy was blocked by the browser.");}};
      const handle=async file=>{if(!file)return;fileName=file.name;$("#bulk-res").innerHTML='<p class="muted">Reading the file…</p>';
        try{if(/\.xlsx?$/i.test(file.name)){await loadXLSX();const wb=XLSX.read(await file.arrayBuffer(),{type:"array"});const sh=wb.Sheets["Users"]||wb.Sheets[wb.SheetNames[0]];parsed={data:XLSX.utils.sheet_to_json(sh,{header:1,raw:false,defval:""})};}
          else parsed={data:parseDelimited(await file.text())};}
        catch(e){parsed={fatal:/\.xlsx?$/i.test(file.name)?"Couldn't read that Excel file. Save it as .csv and try again.":"Couldn't read that file."};}
        if(parsed.data&&!parsed.data.length)parsed={fatal:"The file is empty."};render();};
      $("#bulk-file").onchange=e=>handle(e.target.files[0]);
      const dz=$("#bulk-drop");["dragover","dragenter"].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add("over");}));["dragleave","drop"].forEach(ev=>dz.addEventListener(ev,()=>dz.classList.remove("over")));dz.addEventListener("drop",e=>{e.preventDefault();handle(e.dataTransfer.files[0]);});
      $("#bulk-pastego").onclick=()=>{const t=$("#bulk-paste").value.trim();if(!t){toast("Paste the header row and at least one user.");return;}fileName="Pasted rows";parsed={data:parseDelimited(t)};render();};
      $("#bulk-upd").onchange=e=>{opts.update=e.target.checked;render();};$("#bulk-inv").onchange=e=>{opts.invite=e.target.checked;};
      $("#bulk-go").onclick=()=>{if(!parsed||!parsed.v)return;let cr=0,up=0;const now=new Date().toLocaleString("en-CA",{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"});
        parsed.v.rows.forEach((r,i)=>{if(r.action!=="create"&&r.action!=="update")return;let x;
          if(r.action==="create"){x={id:"b"+Date.now()+"_"+i,name:r.name,title:r.title,email:r.email,brand:r.brand,role:r.role,store:r.store,status:r.status,auth:"—",last:"Never",lastDays:null};S.users.push(x);cr++;if(opts.invite)inviteMail(x,u);}
          else{x=r.existing;Object.assign(x,{name:r.name,title:r.title||x.title,role:r.role,store:r.store,brand:r.brandIn?r.brand:x.brand});if(r.statusIn)x.status=r.status;up++;}
          x.prov=PROV[x.store]||"BC";
          if(r.role==="dm")r.distNos.forEach(no=>{const f=S.fleet.find(z=>z.no===no);f.dm=x.id;f.flTemp=false;setFL(f);f.history=f.history||[];f.history.push({t:now,w:u.name,a:`District manager set to ${x.name} (bulk upload)`});});});
        logA(`Bulk upload "${fileName}": ${cr} created, ${up} updated${opts.invite&&cr?`, ${cr} invites emailed`:""}`);
        save();closeModal();renderApp();toast(`${cr} user${cr===1?"":"s"} created${up?`, ${up} updated`:""}.${opts.invite&&cr?" Invites emailed.":""}`);};
    });
}

/* ---------------- Service requests ---------------- */
const NOW=new Date();
const SR_ST={new:{l:"New",c:"info",ic:"●"},assigned:{l:"Assigned",c:"info",ic:"●"},scheduled:{l:"Scheduled",c:"info",ic:"◷"},in_progress:{l:"In progress",c:"warn",ic:"▶"},on_hold:{l:"On hold",c:"warn",ic:"Ⅱ"},resolved:{l:"Resolved · awaiting confirmation",c:"good",ic:"✓"},closed:{l:"Closed",c:"good",ic:"✓"},cancelled:{l:"Cancelled",c:"crit",ic:"✕"}};
const SR_OPEN=["new","assigned","scheduled","in_progress","on_hold"];
const SR_PRI={emergency:{l:"Emergency",c:"crit",d:"Store can't operate, or there's a safety or security risk. Also phone your district manager."},high:{l:"High",c:"warn",d:"Affects sales or customers today."},normal:{l:"Normal",c:"info",d:"Needs fixing, but the store runs fine."},low:{l:"Low",c:"",d:"Cosmetic or whenever convenient."}};
const SR_LOC=["Sales floor","Cash wrap / POS","Back room / storage","Vault / safe room","Office","Washroom","Staff room","Entrance / storefront","Exterior / parking","Whole store"];
const HOLD_REASONS=["Waiting on parts","Waiting on vendor","Waiting on quote approval","Waiting on store access","Waiting on landlord","Other"];
function seedServiceConfig(){return {
  depts:[{id:"fac",name:"Facilities & Maintenance",email:"facilities@inspiredcannabis.ca",members:["u3","u1"],lead:"u3",ccDM:true},
         {id:"it",name:"IT & Technology",email:"itsupport@inspiredcannabis.ca",members:["u2","u1"],lead:"u2",ccDM:false},
         {id:"sec",name:"Security & Loss Prevention",email:"security@inspiredcannabis.ca",members:["u1","u2"],lead:"u1",ccDM:true}],
  cats:[["Plumbing","fac"],["Electrical","fac"],["IT / Technology (Software)","it"],["IT / Technology (Hardware)","it"],["HVAC","fac"],["Windows / Doors","fac"],["Millwork","fac"],["Locks","sec"],["Doors","fac"],["Floors","fac"],["Ceiling","fac"],["Paint / Drywall","fac"],["Exterior Cleaning","fac"],["Exterior Graffiti","fac"],["Security System","sec"],["Camera System","sec"],["Music System","it"],["Digital Store Displays","it"],["Furniture (Office)","fac"],["Furniture (Sales Floor)","fac"],["Glass Repair","fac"]].map(([name,dept])=>({name,dept})),
  sla:{emergency:4,high:24,normal:72,low:168},seq:1041};}
const deptById=id=>S.sd.depts.find(d=>d.id===id)||S.sd.depts[0];
const catDept=c=>(S.sd.cats.find(x=>x.name===c)||{dept:"fac"}).dept;
const fmtDT=s=>{const d=new Date(s);return d.toLocaleDateString("en-CA",{month:"short",day:"numeric"})+", "+d.toLocaleTimeString("en-CA",{hour:"numeric",minute:"2-digit"});};
function durTxt(ms){const h=Math.abs(ms)/36e5;return h<1?Math.max(1,Math.round(h*60))+"m":h<48?Math.round(h)+"h":Math.round(h/24)+"d";}
const isAgent=(u,t)=>lvl(u)>=4||deptById(t?t.dept:"fac").members.includes(u.id)||(!t&&S.sd.depts.some(d=>d.members.includes(u.id)));
function srVisible(u,t){if(lvl(u)>=3&&u.role!=="dm")return true;if(u.role==="dm"){const f=fleetByName(t.store);return (f&&f.dm===u.id)||t.requester===u.id;}return t.store===u.store||t.requester===u.id;}
function slaInfo(t){if(!SR_OPEN.includes(t.status))return null;if(t.status==="on_hold"||t.status==="scheduled")return {left:9e11,over:false,paused:true,txt:t.status==="scheduled"&&t.visit?"Visit "+fmtDate(t.visit):"Paused"};const left=new Date(t.due)-NOW;return {left,over:left<0,txt:left<0?"Overdue "+durTxt(left):"Due in "+durTxt(left)};}
const srPill=s=>`<span class="st st-${SR_ST[s].c}">${SR_ST[s].ic} ${SR_ST[s].l}</span>`;
const priPill=p=>`<span class="st ${SR_PRI[p].c?"st-"+SR_PRI[p].c:"st-plain"}">${p==="emergency"?"‼ ":""}${SR_PRI[p].l}</span>`;
function slaPill(t){const s=slaInfo(t);if(!s)return '<span class="muted">—</span>';return `<span class="st ${s.over?"st-crit":s.left<6*36e5?"st-warn":"st-plain"}">${s.over?"! ":""}${s.txt}</span>`;}
/* --- notifications: logged on the request and emailed through the portal mailbox --- */
const portalUrl=()=>location.origin+"/";
function srEmail(t,at,to,subject,lines){const body=lines.filter(l=>l!==null&&l!==undefined).concat(["","Open the request: "+portalUrl()+"#service/"+t.id,"","Inspired Group Retail Ops Portal"]).join("\n");
  const rcpt=[...new Set(to.filter(Boolean).map(e=>String(e).trim().toLowerCase()).filter(e=>/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)))];
  t.log.push({t:at,type:"email",to:rcpt,subject,body});
  if(rcpt.length&&DB.queueMail)DB.queueMail(Object.assign({to:rcpt.slice(0,10),subject,text:body,ref:"sr:"+t.id},["emergency","high"].includes(t.priority)?slackOpt("sr"):{}));}
/* --- account emails --- */
function signInHow(){return ["How to sign in:","• If your work email is on Microsoft 365 (Outlook), choose \"Sign in with Microsoft 365\".","• If it's on Google (Gmail), choose \"Sign in with Google\".","• Or enter your email under \"Email me a link\" and open the link we send you."];}
function inviteMail(x,by,again){const first=(x.name||"").split(" ")[0]||"there";
  DB.queueMail&&DB.queueMail({to:[x.email],subject:again?"Reminder: your ICG Retail Ops Portal invite":"You're invited to the ICG Retail Ops Portal",ref:"invite:"+x.email,
    text:[`Hi ${first},`,"",`${by.name} has given you access to the Inspired Group Retail Operations Portal: news and tasks (The Grind), service requests, resources and more.`,"",`Go to: ${portalUrl()}`,`Sign in with this email address: ${x.email}`,"",...signInHow(),"","If you weren't expecting this, you can ignore this email.","","Inspired Group Retail Ops Portal"].join("\n")});}
function approvedMail(x){const first=(x.name||"").split(" ")[0]||"there";
  DB.queueMail&&DB.queueMail({to:[x.email],subject:"Your ICG Retail Ops Portal access is approved",ref:"approved:"+x.email,
    text:[`Hi ${first},`,"","Your request for access to the Inspired Group Retail Operations Portal has been approved.","",`Go to: ${portalUrl()}`,`Sign in with: ${x.email}`,"",...signInHow(),"","Inspired Group Retail Ops Portal"].join("\n")});}
function storeEmail(t){const f=fleetByName(t.store);return f&&f.email;}
function dmEmail(t){const f=fleetByName(t.store);const d=f&&dmOf(f);return d&&d.name!=="Unknown"?d.email:null;}
function notify(t,kind,at,extra){extra=extra||{};const dp=deptById(t.dept);const req=userById(t.requester);const asg=t.assignee?userById(t.assignee):null;
  const head=`[${t.no}] ${t.title}`;const facts=[`Store: ${t.store}`,`Category: ${t.cat} · Priority: ${SR_PRI[t.priority].l}`,`Location: ${t.loc}`];
  if(kind==="created"){srEmail(t,at,[dp.email,asg&&asg.email,dp.ccDM||t.priority==="emergency"?dmEmail(t):null],`New ${t.priority==="emergency"?"EMERGENCY ":""}service request ${head}`,[`A new request was submitted by ${req.name} (${t.contact||req.name}${t.phone?", "+t.phone:""}).`,...facts,`Due (SLA): ${fmtDT(t.due)}`,"",t.desc]);
    srEmail(t,at,[req.email,storeEmail(t)],`We received your request ${t.no}`,[`Hi ${req.name.split(" ")[0]},`,"",`Your request "${t.title}" was received and sent to ${dp.name}.`,...facts,`Target: ${fmtDT(t.due)}`,"","You'll get an email each time the status changes."]);}
  else if(kind==="assigned")srEmail(t,at,[req.email,asg&&asg.email],`${head}: assigned to ${asg.name}`,[`${asg.name} (${dp.name}) is now handling this request.`,...facts]);
  else if(kind==="scheduled")srEmail(t,at,[req.email,storeEmail(t),asg&&asg.email],`${head}: visit scheduled ${fmtDate(t.visit)}`,[`A visit is scheduled for ${new Date(t.visit+"T12:00").toLocaleDateString("en-CA",{weekday:"long",month:"long",day:"numeric"})}${t.window?", "+t.window:""}.`,t.vendor?`Vendor: ${t.vendor}`:"","Please make sure someone can give access to the area.",...facts]);
  else if(kind==="in_progress")srEmail(t,at,[req.email],`${head}: work in progress`,[`Work has started on your request.`,...facts]);
  else if(kind==="on_hold")srEmail(t,at,[req.email,storeEmail(t)],`${head}: on hold`,[`This request is on hold: ${t.hold}.`,extra.note||"","We'll email you when work resumes."]);
  else if(kind==="resolved")srEmail(t,at,[req.email,storeEmail(t)],`${head}: resolved, please confirm`,[`${asg?asg.name:dp.name} marked this request as resolved:`,"",t.resolution,"","Please open the request and confirm it's fixed, or reopen it if it isn't."]);
  else if(kind==="closed")srEmail(t,at,[req.email,asg&&asg.email],`${head}: closed`,[extra.byReq?`${req.name} confirmed the fix. This request is closed.`:"This request is closed."]);
  else if(kind==="reopened")srEmail(t,at,[dp.email,asg&&asg.email],`${head}: REOPENED`,[`${extra.who} reopened this request:`,"",extra.note||"(no reason given)"]);
  else if(kind==="cancelled")srEmail(t,at,[dp.email,asg&&asg.email,req.email],`${head}: cancelled`,[`Cancelled by ${extra.who}.`,extra.note||""]);
  else if(kind==="comment")srEmail(t,at,extra.toAgent?[asg?asg.email:dp.email]:[req.email,storeEmail(t)],`${head}: new update from ${extra.who}`,[extra.note]);
  else if(kind==="rerouted")srEmail(t,at,[dp.email],`${head}: transferred to ${dp.name}`,[`This request was moved to ${dp.name}.`,...facts]);
}
function srLog(t,at,type,by,text,extra){t.log.push(Object.assign({t:at,type,by,text},extra||{}));t.updated=at;}
function createTicket(d,at){const no="SR-"+(++S.sd.seq);const dept=catDept(d.cat);const dp=deptById(dept);
  const t=Object.assign({id:"t"+Date.now().toString(36),no,dept,status:"new",assignee:null,created:at,updated:at,visit:"",window:"",vendor:"",hold:"",resolution:"",atts:[],log:[]},d);
  t.due=new Date(new Date(at).getTime()+S.sd.sla[t.priority]*36e5).toISOString();
  srLog(t,at,"create",t.requester,`Opened ${no} · routed to ${dp.name}`);notify(t,"created",at);S.tickets.unshift(t);return t;}
function srSetStatus(t,st,by,at,extra){extra=extra||{};const was=t.status;t.status=st;
  if(st==="resolved"){t.resolution=extra.resolution;t.resolvedAt=at;}if(st==="on_hold")t.hold=extra.hold;
  srLog(t,at,"status",by,`${SR_ST[was].l.split(" ·")[0]} → ${SR_ST[st].l.split(" ·")[0]}`+(extra.note?`: ${extra.note}`:""),{pub:true});
  notify(t,extra.reopen?"reopened":st,at,extra);syncVisitEvent(t);}
function srAssign(t,uid,by,at){t.assignee=uid;srLog(t,at,"assign",by,`Assigned to ${userById(uid).name}`);if(t.status==="new"){t.status="assigned";}notify(t,"assigned",at);}
/* Service visits show on the calendar, but they're built from the service requests each person is
   allowed to load (restricted by the database), not stored in the shared calendar. */
function syncVisitEvent(t){S.events=S.events.filter(e=>e.ticketId!==t.id);}
