/* --- views --- */
const reqOf=t=>t.reqName?{name:t.reqName,email:t.reqEmail||""}:userById(t.requester);
function srScope(u){return S.tickets.filter(t=>srVisible(u,t));}
/* Requests waiting on this person: assigned to them and not started, new and unassigned in a
   department they belong to, or resolved and waiting for them (requester) to confirm the fix. */
function srWaitWhy(u,t){
  if(t.assignee===u.id&&["new","assigned"].includes(t.status))return "assigned";
  if(!t.assignee&&t.status==="new"&&deptById(t.dept).members.includes(u.id))return "queue";
  if(t.status==="resolved"&&(t.requester===u.id||(lvl(u)<=2&&t.store===u.store)))return "confirm";
  return "";}
function srWaiting(u){return srScope(u).filter(t=>srWaitWhy(u,t));}
